return ['domain'=>'vireo-analytics','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'Vireo Analytics 0.3.2','pot-creation-date'=>'2026-10-15T14:42:49+00:00','po-revision-date'=>'2026-07-18 12:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Vireo Analytics'=>'Vireo Analytics','Privacy-first WordPress analytics. Clean dashboard, no cookies, no consent banners, no third-party tracking.'=>'Datenschutzfreundliche WordPress-Analyse. Übersichtliches Dashboard, keine Cookies, keine Einwilligungsbanner, kein Tracking durch Dritte.','RebelCode'=>'RebelCode','https://rebelcode.com'=>'https://rebelcode.com','Vireo Analytics backup'=>'Vireo-Analytics-Backup','That file is larger than this server accepts (%s). Ask your host to raise the upload limit, or restore in smaller pieces.'=>'Die Datei ist größer, als dieser Server zulässt (%s). Bitte deinen Hoster, das Upload-Limit zu erhöhen, oder stelle die Sicherung in kleineren Teilen wieder her.','The upload did not complete. Try again.'=>'Der Upload wurde nicht abgeschlossen. Versuche es noch einmal.','The uploads directory is not writable, so the file cannot be kept while it is read.'=>'Das Upload-Verzeichnis ist nicht beschreibbar, daher kann die Datei beim Einlesen nicht zwischengespeichert werden.','The file could not be saved for reading.'=>'Die Datei konnte nicht zum Einlesen gespeichert werden.','The file could not be opened.'=>'Die Datei konnte nicht geöffnet werden.','The file is damaged: a line could not be read.'=>'Die Datei ist beschädigt: Eine Zeile konnte nicht gelesen werden.','The file ends early. It may not have finished downloading; export it again.'=>'Die Datei endet vorzeitig. Möglicherweise wurde der Download nicht abgeschlossen; exportiere sie erneut.','That is not a Vireo Analytics backup. Use the file from Settings, Import & export, Download backup.'=>'Das ist keine Vireo-Analytics-Sicherung. Verwende die Datei aus Einstellungen, Import & Export, Sicherung herunterladen.','This backup was made by a newer version of Vireo Analytics. Update the plugin here, then try again.'=>'Diese Sicherung wurde mit einer neueren Version von Vireo Analytics erstellt. Aktualisiere das Plugin hier und versuche es dann erneut.','Upload a backup file first.'=>'Lade zuerst eine Sicherungsdatei hoch.','The uploaded file is no longer available. Upload it again.'=>'Die hochgeladene Datei ist nicht mehr verfügbar. Lade sie erneut hoch.','Restored. %d part of the file was for a table this version does not have and was skipped.'=>'Wiederhergestellt. %d Teil der Datei gehörte zu einer Tabelle, die es in dieser Version nicht gibt, und wurde übersprungen.' . "\0" . 'Wiederhergestellt. %d Teile der Datei gehörten zu Tabellen, die es in dieser Version nicht gibt, und wurden übersprungen.','Restored.'=>'Wiederhergestellt.','Restoring %s'=>'%s wird wiederhergestellt','daily totals'=>'Tagessummen','bounce rates'=>'Absprungraten','hourly totals'=>'Stundensummen','pages'=>'Seiten','time on page'=>'Verweildauer auf der Seite','referrers'=>'Verweisquellen','referrers per page'=>'Referrer pro Seite','countries'=>'Länder','devices'=>'Geräte','missing pages'=>'fehlende Seiten','events'=>'Ereignisse','bot traffic'=>'Bot-Traffic','Core Web Vitals'=>'Core Web Vitals','chart notes'=>'Diagramm-Notizen','Search Console queries'=>'Search-Console-Suchanfragen','Search Console pages'=>'Search-Console-Seiten','Burst Statistics'=>'Burst Statistics','No Burst Statistics data found.'=>'Keine Burst Statistics-Daten gefunden.','Burst Statistics import complete.'=>'Burst Statistics-Import abgeschlossen.','Imported %1$d of %2$d day from Burst Statistics.'=>'%1$d von %2$d Tag aus Burst Statistics importiert.' . "\0" . '%1$d von %2$d Tagen aus Burst Statistics importiert.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices and missing pages.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Verweisquellen, zu welchen Beiträgen jede Verweisquelle Leser geschickt hat, Länder, Browser, Betriebssysteme, Geräte und fehlende Seiten.','Google Analytics 4'=>'Google Analytics 4','Add the service account key and the GA4 property ID first.'=>'Dienstkontoschlüssel und GA4-Property-ID zuerst hinzufügen.','The date range is not valid.'=>'Der Zeitraum ist ungültig.','Imported %1$s to %2$s'=>'%1$s bis %2$s importiert','Google refused the request. Check the service account has Viewer access on this GA4 property.'=>'Google hat die Anfrage abgelehnt. Prüfen, ob das Dienstkonto Betrachterzugriff auf diese GA4-Property hat.','Google Analytics returned an unexpected response (HTTP %d).'=>'Google Analytics hat eine unerwartete Antwort geliefert (HTTP %d).','Google Analytics returned a response we could not read.'=>'Google Analytics hat eine Antwort geliefert, die sich nicht lesen ließ.','Import complete'=>'Import abgeschlossen','Import stopped'=>'Import gestoppt','Independent Analytics'=>'Independent Analytics','No Independent Analytics data found.'=>'Keine Independent Analytics-Daten gefunden.','Independent Analytics import complete.'=>'Independent Analytics-Import abgeschlossen.','Imported %1$d of %2$d day from Independent Analytics.'=>'%1$d von %2$d Tag aus Independent Analytics importiert.' . "\0" . '%1$d von %2$d Tagen aus Independent Analytics importiert.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, and tracked link clicks and form submissions as events.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Verweisquellen, zu welchen Beiträgen jede Verweisquelle Leser geschickt hat, Länder, Browser, Betriebssysteme, Geräte, fehlende Seiten sowie getrackte Link-Klicks und Formularübermittlungen als Ereignisse.','Jetpack Stats'=>'Jetpack Stats','Importing %1$s — %2$s'=>'%1$s – %2$s wird importiert','Missing import parameters. Please submit the form again.'=>'Fehlende Import-Parameter. Bitte senden Sie das Formular erneut ab.','Invalid date range — please use YYYY-MM-DD.'=>'Ungültiger Datumsbereich – bitte verwenden Sie das Format YYYY-MM-DD.','End date must be on or after start date.'=>'Das Enddatum muss am oder nach dem Startdatum liegen.','Complete'=>'Abgeschlossen','Could not reach Jetpack Stats API: %s'=>'Die Jetpack-Stats-API konnte nicht erreicht werden: %s','Unexpected (non-JSON) response from Jetpack Stats API.'=>'Unerwartete (nicht-JSON) Antwort von der Jetpack-Stats-API.','Invalid or unauthorized API key. Copy your WordPress.com API key from Jetpack → Settings → Security → Akismet.'=>'Ungültiger oder nicht autorisierter API-Schlüssel. Kopieren Sie Ihren WordPress.com-API-Schlüssel aus Jetpack → Einstellungen → Sicherheit → Akismet.','Jetpack Stats API is rate-limiting — please wait a minute and try again.'=>'Die Jetpack-Stats-API drosselt die Anfragen – bitte warten Sie eine Minute und versuchen Sie es erneut.','Jetpack Stats API is unavailable right now. Please retry in a few minutes.'=>'Die Jetpack-Stats-API ist derzeit nicht verfügbar. Bitte versuchen Sie es in einigen Minuten erneut.','Jetpack Stats API returned an error (HTTP %d). Check your API key and blog URI.'=>'Die Jetpack-Stats-API hat einen Fehler zurückgegeben (HTTP %d). Prüfen Sie Ihren API-Schlüssel und die Blog-URI.','Koko Analytics'=>'Koko Analytics','No Koko Analytics data found.'=>'Keine Koko-Analytics-Daten gefunden.','Plausible Analytics'=>'Plausible Analytics','No Plausible reports were found in that upload. Upload the zip file Plausible emailed you, or the CSV files inside it.'=>'In diesem Upload wurden keine Plausible-Berichte gefunden. Lade die ZIP-Datei hoch, die Plausible dir per E-Mail geschickt hat, oder die darin enthaltenen CSV-Dateien.','The export has no traffic in the dates you chose.'=>'Der Export enthält keinen Traffic in den ausgewählten Zeiträumen.','Upload a Plausible export first.'=>'Lade zuerst einen Plausible-Export hoch.','The uploaded export is no longer available. Upload it again; dates already imported are listed on this screen.'=>'Der hochgeladene Export ist nicht mehr verfügbar. Lade ihn erneut hoch. Bereits importierte Tage sind auf diesem Bildschirm aufgeführt.','The file did not upload. It may be larger than this server accepts.'=>'Die Datei wurde nicht hochgeladen. Möglicherweise ist sie größer, als dieser Server zulässt.','That file is too large. Export a shorter date range from Plausible and import it in parts.'=>'Die Datei ist zu groß. Exportiere in Plausible einen kürzeren Datumsbereich und importiere ihn in mehreren Teilen.','Upload the .zip file Plausible gave you, or the .csv files inside it.'=>'Lade die ZIP-Datei hoch, die du von Plausible bekommen hast, oder die darin enthaltenen CSV-Dateien.','The uploaded file could not be read.'=>'Die hochgeladene Datei konnte nicht gelesen werden.','This server cannot open zip files. Unzip the export on your computer and upload the CSV files instead.'=>'Dieser Server kann keine ZIP-Dateien öffnen. Entpacke den Export auf deinem Computer und lade stattdessen die CSV-Dateien hoch.','That zip file could not be opened.'=>'Diese ZIP-Datei konnte nicht geöffnet werden.','That zip holds more files than a Plausible export does.'=>'Diese ZIP-Datei enthält mehr Dateien, als ein Plausible-Export umfasst.','A file inside the zip could not be read.'=>'Eine Datei in der ZIP-Datei konnte nicht gelesen werden.','The %1$s file is missing its %2$s column.'=>'In der Datei %1$s fehlt die Spalte %2$s.','That export is too large to import in one go. Choose a shorter date range and import it in parts.'=>'Dieser Export ist zu groß, um ihn in einem Durchgang zu importieren. Wähle einen kürzeren Datumsbereich und importiere ihn in mehreren Teilen.','SlimStat Analytics'=>'SlimStat Analytics','No SlimStat data found.'=>'Keine SlimStat-Daten gefunden.','SlimStat import complete.'=>'SlimStat-Import abgeschlossen.','Imported %1$d of %2$d day from SlimStat.'=>'%1$d von %2$d Tag aus SlimStat importiert.' . "\0" . '%1$d von %2$d Tagen aus SlimStat importiert.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, downloads and outbound clicks, and the crawlers SlimStat recorded, as filtered bots rather than visits.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Verweisquellen, zu welchen Beiträgen jede Verweisquelle Leser geschickt hat, Länder, Browser, Betriebssysteme, Geräte, fehlende Seiten, Downloads und ausgehende Klicks sowie die von SlimStat erfassten Crawler als gefilterte Bots statt als Besuche.','Statify'=>'Statify','No Statify data found.'=>'Keine Statify-Daten gefunden.','Statify import complete.'=>'Statify-Import abgeschlossen.','Imported %1$d of %2$d day from Statify.'=>'%1$d von %2$d Tag aus Statify importiert.' . "\0" . '%1$d von %2$d Tagen aus Statify importiert.','Brings across daily pageviews, your pages, referrers and which posts each referrer sent readers to. Statify does not identify visitors, so imported days have no visitor counts.'=>'Übernimmt tägliche Seitenaufrufe, deine Seiten, Verweisquellen und zu welchen Beiträgen jede Verweisquelle Leser geschickt hat. Statify erkennt Besucher nicht wieder, daher haben importierte Tage keine Besucherzahlen.','WP Statistics'=>'WP Statistics','No WP Statistics data found.'=>'Keine WP Statistics-Daten gefunden.','WP Statistics import complete.'=>'WP Statistics-Import abgeschlossen.','Imported %1$d of %2$d day from WP Statistics.'=>'%1$d von %2$d Tag aus WP Statistics importiert.' . "\0" . '%1$d von %2$d Tagen aus WP Statistics importiert.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, link clicks, downloads and custom events, and, if WP Statistics recorded exclusions, the bots it filtered out.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Verweisquellen, zu welchen Beiträgen jede Verweisquelle Leser geschickt hat, Länder, Browser, Betriebssysteme, Geräte, fehlende Seiten, Link-Klicks, Downloads und benutzerdefinierte Ereignisse sowie, falls WP Statistics Ausschlüsse erfasst hat, die herausgefilterten Bots.','Read-only site analytics: traffic, pages, referrers, geography, devices, and events.'=>'Schreibgeschützte Website-Analyse: Traffic, Seiten, Verweisquellen, Geografie, Geräte und Ereignisse.','Get traffic totals'=>'Traffic-Summen abrufen','Total pageviews, unique visitors, average daily pageviews, average time on page and bounce rate for a date range (defaults to the last 30 days). Time on page is active time (the tab in front of the reader, at most 30 minutes a view), averaged over the views that reported one. Bounce rate is the percentage of visitors who viewed exactly one page in a day. Both are null until there is data for the range.'=>'Seitenaufrufe gesamt, eindeutige Besucher, durchschnittliche Seitenaufrufe pro Tag, durchschnittliche Verweildauer auf der Seite und Absprungrate für einen Zeitraum (Standard: die letzten 30 Tage). Die Verweildauer ist die aktive Zeit (der Tab ist im Vordergrund, höchstens 30 Minuten pro Aufruf), gemittelt über die Aufrufe, die eine Zeit gemeldet haben. Die Absprungrate ist der Prozentsatz der Besucher, die an einem Tag genau eine Seite aufgerufen haben. Beide sind null, bis es Daten für den Zeitraum gibt.','Get daily traffic series'=>'Tägliche Traffic-Reihe abrufen','Per-day pageviews and visitors over a date range, for charting trends.'=>'Seitenaufrufe und Besucher pro Tag über einen Datumsbereich, zur Darstellung von Trends.','Get top pages'=>'Top-Seiten abrufen','Most-viewed pages for a date range, ranked by pageviews, with each page\'s average active time on page in seconds (null when no view of it reported a time).'=>'Meistaufgerufene Seiten für einen Zeitraum, nach Seitenaufrufen sortiert, mit der durchschnittlichen aktiven Verweildauer pro Seite in Sekunden (null, wenn kein Aufruf eine Zeit gemeldet hat).','Get top referrers'=>'Top-Verweisquellen abrufen','Top referring sites sending traffic for a date range.'=>'Wichtigste verweisende Websites, die in einem Datumsbereich Traffic senden.','Get traffic by country'=>'Traffic nach Land abrufen','Visitor counts broken down by country for a date range.'=>'Besucherzahlen aufgeschlüsselt nach Land für einen Datumsbereich.','Get device breakdown'=>'Geräteaufschlüsselung abrufen','Visitor breakdown by browser, operating system, and device type for a date range.'=>'Besucheraufschlüsselung nach Browser, Betriebssystem und Gerätetyp für einen Datumsbereich.','Get custom events'=>'Benutzerdefinierte Ereignisse abrufen','Top custom events for a date range. Pass a `name` to break a single event down by value.'=>'Wichtigste benutzerdefinierte Ereignisse für einen Datumsbereich. Übergeben Sie einen `name`, um ein einzelnes Ereignis nach Wert aufzuschlüsseln.','Optional event name to break down by value.'=>'Optionaler Ereignisname zur Aufschlüsselung nach Wert.','Get stats for a post'=>'Statistiken für einen Beitrag abrufen','Lifetime and date-range pageviews/visitors, a daily series, and the top referrers for a single post or page. Use get-top-pages first if you only have a title or path.'=>'Gesamte und zeitraumbezogene Seitenaufrufe/Besucher, eine Tagesreihe und die wichtigsten Referrer für einen einzelnen Beitrag oder eine einzelne Seite. Verwende zuerst get-top-pages, wenn du nur einen Titel oder Pfad hast.','The post or page ID to report on.'=>'Die ID des Beitrags oder der Seite, für die berichtet werden soll.','Get hourly traffic series'=>'Stündliche Traffic-Reihe abrufen','Pageviews and visitors per hour, for "what time of day do people visit" and for looking at today or yesterday in detail. Covers at most two days; longer ranges are cut to the last two days. Defaults to today.'=>'Seitenaufrufe und Besucher pro Stunde, für die Frage „Zu welcher Tageszeit besuchen Leute die Website?“ und für eine detaillierte Ansicht von heute oder gestern. Deckt höchstens zwei Tage ab; längere Zeiträume werden auf die letzten zwei Tage gekürzt. Standardmäßig heute.','Get what changed'=>'Änderungen abrufen','What changed against the previous period of the same length: a one-sentence summary, the pages and traffic sources that gained or lost the most, shifts in the traffic mix, and health warnings such as tracking having stopped or a 404 spike. Call this first when asked "how is the site doing" or "why is traffic up/down".'=>'Was sich gegenüber dem vorherigen Zeitraum gleicher Länge geändert hat: eine Zusammenfassung in einem Satz, die Seiten und Traffic-Quellen mit den größten Zugewinnen oder Verlusten, Verschiebungen im Traffic-Mix und Warnungen zum Zustand, etwa wenn das Tracking ausgefallen ist oder die 404-Fehler sprunghaft ansteigen. Rufe dies zuerst auf, wenn gefragt wird „Wie läuft die Website?“ oder „Warum steigt/sinkt der Traffic?“.','Get weekly highlights'=>'Wöchentliche Highlights abrufen','Short, ready-to-quote highlights for a finished week: milestones crossed, the biggest gaining page, a new referrer, the best day. Defaults to the last seven full days. Returns an empty list when nothing stood out.'=>'Kurze, zitierfertige Highlights für eine abgeschlossene Woche: erreichte Meilensteine, die Seite mit dem größten Zugewinn, ein neuer Referrer, der beste Tag. Standardmäßig die letzten sieben vollen Tage. Gibt eine leere Liste zurück, wenn nichts herausstach.','Get traffic by channel'=>'Traffic nach Kanal abrufen','Pageviews and visitors grouped by how people arrived: direct, search engines, AI assistants, social networks, and other referring sites, with each channel\'s share. Use get-top-referrers for the individual sites inside a channel.'=>'Seitenaufrufe und Besucher, gruppiert danach, wie die Leute auf die Website gekommen sind: direkt, über Suchmaschinen, KI-Assistenten, soziale Netzwerke und andere verweisende Websites, jeweils mit dem Anteil des Kanals. Verwende get-top-referrers für die einzelnen Websites innerhalb eines Kanals.','Get stats for one referrer'=>'Statistiken zu einem Referrer abrufen','Everything about traffic from one referring site: pageviews and visitors in the range, a daily series, and which of your pages it sent people to. Pass the host as shown by get-top-referrers, for example "news.ycombinator.com".'=>'Alles zum Traffic von einer verweisenden Website: Seitenaufrufe und Besucher im Zeitraum, eine Tagesreihe und die Seiten, auf die sie Besucher geschickt hat. Gib den Host so an, wie ihn get-top-referrers anzeigt, zum Beispiel „news.ycombinator.com“.','The referring site, as a hostname or URL.'=>'Die verweisende Website, als Hostname oder URL.','Get AI assistant traffic'=>'KI-Assistenten-Traffic abrufen','What AI assistants take and what they send back: requests made by AI crawlers (GPTBot, ClaudeBot, PerplexityBot and others) against readers (visitors) that ChatGPT, Claude, Perplexity, Gemini and the rest referred to the site, per assistant, with the ratio of crawler requests per reader sent. Everything covers the days crawlers were counted; when that starts later than the requested range, `since` holds that date.'=>'Was KI-Assistenten abrufen und was sie zurückschicken: Anfragen von KI-Crawlern (GPTBot, ClaudeBot, PerplexityBot und andere) im Vergleich zu Lesern (Besuchern), die ChatGPT, Claude, Perplexity, Gemini und die übrigen Assistenten auf die Website verwiesen haben, pro Assistent, mit dem Verhältnis von Crawler-Anfragen pro gesendetem Leser. Alles bezieht sich auf die Tage, an denen Crawler gezählt wurden; beginnt dieser Zeitraum später als der angefragte, enthält `since` dieses Datum.','Get Google Search Console data'=>'Google-Search-Console-Daten abrufen','Google Search performance synced from Search Console: site-wide clicks, impressions, CTR and average position plus the top search queries, or, when post_id or path is given, the queries that brought people to that one page. Returns connected=false with no data when Search Console is not connected under Settings. Google\'s data lags two to three days behind.'=>'Google-Suchleistung, synchronisiert aus der Search Console: Klicks, Impressionen, CTR und durchschnittliche Position für die gesamte Website sowie die wichtigsten Suchanfragen oder, wenn post_id oder path angegeben ist, die Suchanfragen, die Besucher auf genau diese Seite gebracht haben. Gibt connected=false ohne Daten zurück, wenn die Search Console nicht unter „Einstellungen“ verbunden ist. Die Daten von Google hinken zwei bis drei Tage hinterher.','Optional post or page ID to get the queries for that page only.'=>'Optionale ID eines Beitrags oder einer Seite, um nur die Suchanfragen für diese Seite abzurufen.','Optional page path (for example /pricing) instead of post_id.'=>'Optionaler Seitenpfad (zum Beispiel /pricing) anstelle von post_id.','Get stats for one event'=>'Statistiken zu einem Ereignis abrufen','One custom event in depth: total and unique counts, a daily series, how many distinct values it carried, and the top values. Use get-events to find event names first.'=>'Ein benutzerdefiniertes Ereignis im Detail: Gesamtzahl und eindeutige Anzahl, eine Tagesreihe, wie viele verschiedene Werte es enthielt, und die häufigsten Werte. Verwende zuerst get-events, um Ereignisnamen zu finden.','The event name, as listed by get-events.'=>'Der Ereignisname, wie ihn get-events auflistet.','Get missing pages (404s)'=>'Fehlende Seiten (404) abrufen','Paths that returned 404, ranked by hits. Split into broken links (reached from one of your own pages, with the page that links there, so they can be fixed) and probes (scanners and outside links). Use this for "do I have broken links" and for a 404 spike flagged by get-changes.'=>'Pfade, die einen 404-Fehler zurückgegeben haben, nach Treffern sortiert. Aufgeteilt in defekte Links (von einer deiner eigenen Seiten aus aufgerufen, samt der verlinkenden Seite, damit sie behoben werden können) und Probes (Scanner und externe Links). Verwende dies für die Frage „Habe ich defekte Links?“ und bei einem 404-Anstieg, den get-changes meldet.','Get bot and crawler traffic'=>'Bot- und Crawler-Traffic abrufen','Requests the bot filter rejected, per category (search engines, AI crawlers, SEO tools, monitors, scrapers and so on), with the share of all requests they made up. None of these are in the pageview totals; use this when numbers look lower than another tool\'s, or when asked how much AI crawlers read the site.'=>'Anfragen, die der Bot-Filter abgewiesen hat, pro Kategorie (Suchmaschinen, KI-Crawler, SEO-Tools, Monitore, Scraper und so weiter), mit dem Anteil an allen Anfragen. Keine davon sind in den Seitenaufruf-Summen enthalten; verwende dies, wenn die Zahlen niedriger wirken als in einem anderen Tool oder wenn gefragt wird, wie stark KI-Crawler die Website lesen.','Get Core Web Vitals'=>'Core Web Vitals abrufen','Core Web Vitals (LCP, INP, CLS) measured on real visitors, reported at the 75th percentile the way Google grades them, each with a good/needs-improvement/poor rating and the sample count. Empty when no measurements were recorded in the range.'=>'Core Web Vitals (LCP, INP, CLS), gemessen bei echten Besuchern und beim 75. Perzentil ausgewiesen, so wie Google sie bewertet, jeweils mit einer Bewertung (gut/verbesserungswürdig/schlecht) und der Stichprobengröße. Leer, wenn im Zeitraum keine Messungen aufgezeichnet wurden.','Get chart notes'=>'Diagrammnotizen abrufen','Notes the site owner pinned to dates on the traffic chart, such as "newsletter sent" or "redesign launched". Check these when explaining a spike or a dip, since they often hold the reason.'=>'Notizen, die der Websitebetreiber im Traffic-Diagramm an Daten angeheftet hat, etwa „Newsletter versendet“ oder „Redesign gestartet“. Sieh dir diese an, wenn du einen Anstieg oder Einbruch erklären willst, denn oft stehen dort die Gründe.','Get year in review'=>'Jahresrückblick abrufen','The year in review for one calendar year: totals against the year before, the busiest month and day, the top pages, posts published that year, top referrers, countries, and AI crawler activity. Includes imported history from a previous analytics tool. Defaults to the current year.'=>'Der Jahresrückblick für ein Kalenderjahr: Gesamtwerte im Vergleich zum Vorjahr, der stärkste Monat und Tag, die Top-Seiten, in diesem Jahr veröffentlichte Beiträge, Top-Referrer, Länder und die Aktivität von KI-Crawlern. Enthält importierte Verlaufsdaten aus einem früheren Analyse-Tool. Standardmäßig das aktuelle Jahr.','The calendar year to report on. Defaults to the current year.'=>'Das Kalenderjahr, über das berichtet werden soll. Standardmäßig das aktuelle Jahr.','Get goal completions (Pro)'=>'Zielabschlüsse abrufen (Pro)','Conversion goals with completion counts and total value for a date range. Requires Vireo Analytics Pro.'=>'Conversion-Ziele mit Abschlusszahlen und Gesamtwert für einen Datumsbereich. Erfordert Vireo Analytics Pro.','Post not found.'=>'Beitrag nicht gefunden.','Goals feature unavailable.'=>'Ziel-Funktion nicht verfügbar.','Direct'=>'Direkt','Search'=>'Suche','AI assistants'=>'KI-Assistenten','Social'=>'Soziale Netzwerke','Referral'=>'Verweis','host must be a hostname or URL.'=>'host muss ein Hostname oder eine URL sein.','Google Search Console is not connected. Connect it under Vireo Analytics, Settings, Search Console & API.'=>'Die Google Search Console ist nicht verbunden. Verbinde sie unter Vireo Analytics, Einstellungen, Search Console & API.','name is required.'=>'name ist erforderlich.','year must be a calendar year with data, no later than the current year.'=>'year muss ein Kalenderjahr mit Daten sein, höchstens das aktuelle Jahr.','Unknown ability.'=>'Unbekannte Fähigkeit.','Start date (YYYY-MM-DD). Defaults to 30 days ago.'=>'Startdatum (YYYY-MM-DD). Standard: vor 30 Tagen.','End date (YYYY-MM-DD). Defaults to today.'=>'Enddatum (YYYY-MM-DD). Standard: heute.','Maximum number of rows to return (1-100).'=>'Maximale Anzahl der zurückzugebenden Zeilen (1–100).','pageviews today'=>'Seitenaufrufe heute','Pageviews today (Vireo Analytics)'=>'Seitenaufrufe heute (Vireo Analytics)','Vireo Analytics is not recording.'=>'Vireo Analytics zeichnet nicht auf.','%1$s. %2$d attempts have failed over the last %3$s. Visits are still being written to disk and will be counted once this clears.'=>'%1$s. %2$d Versuche sind in den letzten %3$s fehlgeschlagen. Besuche werden weiterhin auf die Festplatte geschrieben und gezählt, sobald das Problem behoben ist.','Aggregation is failing'=>'Aggregation schlägt fehl','Pick a real date.'=>'Ein gültiges Datum wählen.','Add a short note to go with the date.'=>'Eine kurze Notiz zum Datum hinzufügen.','Could not save that note.'=>'Die Notiz ließ sich nicht speichern.','That site is no longer connected.'=>'Diese Website ist nicht mehr verbunden.','You are not allowed to add notes.'=>'Du darfst keine Notizen hinzufügen.','You are not allowed to remove notes.'=>'Du darfst keine Notizen entfernen.','That note is already gone.'=>'Diese Notiz ist bereits entfernt.','Forbidden.'=>'Zugriff verweigert.','Failed to open output stream.'=>'Der Ausgabestream konnte nicht geöffnet werden.','AI crawlers'=>'KI-Crawler','Search engines'=>'Suchmaschinen','SEO tools'=>'SEO-Tools','Uptime monitors'=>'Uptime-Monitore','Link previews'=>'Linkvorschauen','Automated browsers'=>'Automatisierte Browser','Scripts and clients'=>'Skripte und Clients','Archivers and validators'=>'Archivierer und Validatoren','Prefetch and prerender'=>'Prefetch und Prerender','Repeated views past the daily cap'=>'Wiederholte Aufrufe über dem Tageslimit','Referrer spam'=>'Referrer-Spam','Other bots'=>'Andere Bots','%s comment'=>'%s Kommentar' . "\0" . '%s Kommentare','%s per 1,000 views'=>'%s pro 1.000 Aufrufe','Traffic chart'=>'Traffic-Diagramm','What changed'=>'Was sich geändert hat','Top pages'=>'Top-Seiten','Top referrers'=>'Top-Verweisquellen','Top countries'=>'Top-Länder','Technology'=>'Technologie','Pageviews today'=>'Seitenaufrufe heute','Compared with yesterday up to the same time of day.'=>'Verglichen mit gestern bis zur gleichen Uhrzeit.','Visitors today'=>'Besucher heute','Right now'=>'Gerade jetzt','Last 14 days'=>'Letzte 14 Tage','Pageviews'=>'Seitenaufrufe','Visitors'=>'Besucher','Pageviews, compared with the period before'=>'Seitenaufrufe, verglichen mit dem Vorzeitraum','7 days'=>'7 Tage','30 days'=>'30 Tage','90 days'=>'90 Tage','Top pages · last 7 days'=>'Top-Seiten · letzte 7 Tage','Top referrers · last 7 days'=>'Top-Verweisquellen · letzte 7 Tage','View full dashboard →'=>'Vollständiges Dashboard anzeigen →','No data yet.'=>'Noch keine Daten.','Home'=>'Startseite','No traffic data yet.'=>'Noch keine Traffic-Daten.','%1$s: %2$s pageviews, %3$s visitors'=>'%1$s: %2$s Seitenaufrufe, %3$s Besucher','Pageviews and visitors, last 14 days'=>'Seitenaufrufe und Besucher, letzte 14 Tage','Day'=>'Tag','Overview'=>'Übersicht','Search & AI'=>'Suche & KI','Page speed'=>'Seitengeschwindigkeit','Content'=>'Inhalte','Campaigns'=>'Kampagnen','Issues'=>'Probleme','Starting…'=>'Wird gestartet…','Import complete.'=>'Import abgeschlossen.','Something went wrong:'=>'Etwas ist schiefgelaufen:','Import cancelled.'=>'Import abgebrochen.','today'=>'heute','yesterday'=>'gestern','last 7 days'=>'letzte 7 Tage','last 14 days'=>'letzte 14 Tage','last 30 days'=>'letzte 30 Tage','last 90 days'=>'letzte 90 Tage','this month'=>'dieser Monat','last month'=>'letzter Monat','year to date'=>'seit Jahresbeginn','Traffic overview · %s'=>'Traffic-Übersicht · %s','Traffic overview · %1$s – %2$s'=>'Traffic-Übersicht · %1$s – %2$s','(no path)'=>'(kein Pfad)','Unknown'=>'Unbekannt','Desktop'=>'Desktop','Mobile'=>'Mobil','Tablet'=>'Tablet','%s visitor vs the prior period'=>'%s Besucher im Vergleich zum Vorzeitraum' . "\0" . '%s Besucher im Vergleich zum Vorzeitraum','No prior-period data'=>'Keine Daten aus dem Vorzeitraum','new'=>'neu','%1$s vs %2$s in the prior period'=>'%1$s gegenüber %2$s im Vorzeitraum','No prior period to compare against yet.'=>'Noch kein Vorzeitraum zum Vergleich vorhanden.','Pageviews are flat on the same period last year.'=>'Die Seitenaufrufe sind gegenüber dem gleichen Zeitraum des Vorjahres unverändert.','Pageviews are flat on the prior period.'=>'Die Seitenaufrufe sind gegenüber dem Vorzeitraum unverändert.','Pageviews are up %d%%.'=>'Die Seitenaufrufe sind um %d%% gestiegen.','Pageviews are down %d%%.'=>'Die Seitenaufrufe sind um %d%% gesunken.','Most of the drop is traffic that stopped coming from %s.'=>'Der Rückgang geht größtenteils auf Traffic zurück, der nicht mehr von %s kommt.','Most of the drop is %s.'=>'Der Rückgang entfällt größtenteils auf %s.','Most of the rise is new traffic from %s.'=>'Der Anstieg geht größtenteils auf neuen Traffic von %s zurück.','Most of the rise is %s.'=>'Der Anstieg entfällt größtenteils auf %s.','%1$s took %2$s more of the mix.'=>'%1$s hat %2$s mehr Anteil am Mix gewonnen.','%1$s lost %2$s of the mix.'=>'%1$s hat %2$s Anteil am Mix verloren.','No pageviews were recorded yesterday, but this site was busy the week before. Tracking may have stopped.'=>'Gestern wurden keine Seitenaufrufe erfasst, obwohl auf dieser Website in der Woche zuvor viel los war. Möglicherweise wurde das Tracking gestoppt.','Every visitor is being recorded as Unknown. Countries will stay empty until geo-location is set up.'=>'Jeder Besucher wird als „Unbekannt“ erfasst. Die Länder bleiben leer, bis die Geolokalisierung eingerichtet ist.','404 errors are up %1$d%%, mostly on %2$s.'=>'Die 404-Fehler sind um %1$d%% gestiegen, überwiegend bei %2$s.','Traffic is down %d%% on the prior period, well beyond normal variation.'=>'Der Traffic ist gegenüber dem Vorzeitraum um %d%% gesunken, deutlich über der normalen Schwankung.','Traffic is up %d%% on the prior period, well beyond normal variation.'=>'Der Traffic ist gegenüber dem Vorzeitraum um %d%% gestiegen, deutlich über der normalen Schwankung.','Daily'=>'Täglich','Weekly'=>'Wöchentlich','Monthly'=>'Monatlich','month and yearF Y'=>'F Y','[%1$s] Daily Analytics: %2$s'=>'[%1$s] Tägliche Analysen: %2$s','[%1$s] Monthly Analytics: %2$s'=>'[%1$s] Monatliche Analysen: %2$s','[%1$s] Weekly Analytics: %2$s'=>'[%1$s] Wöchentliche Analyse: %2$s','no views timed yet'=>'noch keine Aufrufe mit Zeitmessung','Time on page is recorded from this update on. A view reports its time when the reader leaves the page, and the next run of the collector records it, so the first figure appears within a few minutes of the first visit.'=>'Die Verweildauer auf der Seite wird ab diesem Update erfasst. Ein Aufruf meldet seine Dauer, wenn die Besucherin oder der Besucher die Seite verlässt, und der nächste Lauf des Collectors erfasst sie. Der erste Wert erscheint daher wenige Minuten nach dem ersten Besuch.','timed from %s'=>'gemessen seit %s','Time on page has been recorded since %s. This range ends before that, so there is nothing to average.'=>'Die Verweildauer auf der Seite wird seit %s erfasst. Dieser Zeitraum endet davor, daher gibt es nichts zu mitteln.','no views timed in this range'=>'keine gemessenen Aufrufe in diesem Zeitraum','Time on page has been recorded since %s, but no view in this range has reported a time yet. Views report when the reader leaves the page.'=>'Die Verweildauer auf der Seite wird seit %s erfasst, aber in diesem Zeitraum hat noch kein Aufruf eine Dauer gemeldet. Aufrufe melden sie, wenn die Besucherin oder der Besucher die Seite verlässt.','not counted yet'=>'noch nicht erfasst','Bounce rate starts counting once the update has finished setting up, on the next scheduled run or the next visit to wp-admin.'=>'Die Absprungrate wird erfasst, sobald das Update die Einrichtung abgeschlossen hat, beim nächsten geplanten Lauf oder beim nächsten Aufruf von wp-admin.','starts counting %s'=>'Erfassung startet %s','Visitors who arrived before this update were already counted, so bounce rate starts with the first full day, %s.'=>'Besucher, die vor diesem Update kamen, wurden bereits gezählt. Die Absprungrate beginnt daher mit dem ersten vollen Tag, %s.','counted from %s'=>'erfasst seit %s','Bounce rate has been counted since %s. This range ends before that.'=>'Die Absprungrate wird seit %s erfasst. Dieser Zeitraum endet davor.','counted from %s, no visitors yet'=>'erfasst seit %s, noch keine Besucher','Bounce rate has been counted since %s. It fills in with the first run of the collector after a visit, within a few minutes.'=>'Die Absprungrate wird seit %s erfasst. Sie füllt sich mit dem ersten Lauf des Collectors nach einem Besuch, innerhalb weniger Minuten.','%ds'=>'%ds','%1$dm %2$02ds'=>'%1$dm %2$02ds','Event not found.'=>'Ereignis nicht gefunden.','Event · %s'=>'Ereignis · %s','Support'=>'Support','Rate Vireo'=>'Vireo bewerten','You do not have permission to do that.'=>'Dazu hast du keine Berechtigung.','Hourly traffic is stored for the whole site, so the chart shows days while a filter is on.'=>'Der stündliche Traffic wird für die gesamte Website gespeichert, daher zeigt das Diagramm Tage, solange ein Filter aktiv ist.','Referrers are only recorded per page for posts and pages with an ID, so this page can be filtered on its own but not combined with a source or referrer.'=>'Referrer werden pro Seite nur für Beiträge und Seiten mit einer ID erfasst. Diese Seite lässt sich daher einzeln filtern, aber nicht mit einer Quelle oder einem Referrer kombinieren.','device'=>'Gerät','country'=>'Land','source'=>'Quelle','referrer'=>'Referrer','page'=>'Seite',', '=>', ','Vireo keeps daily totals per dimension, not per visit, so filtering by %s together cannot be answered exactly.'=>'Vireo speichert Tagessummen pro Dimension, nicht pro Besuch. Eine Filterung nach %s zusammen lässt sich daher nicht exakt beantworten.','This breakdown is not stored by %s, so it is not shown while that filter is on.'=>'%s speichert diese Aufschlüsselung nicht, deshalb wird sie bei aktivem Filter nicht angezeigt.','The uploads directory is not writable, so the database cannot be saved.'=>'Das Uploads-Verzeichnis ist nicht beschreibbar, daher kann die Datenbank nicht gespeichert werden.','Could not download the database: %s'=>'Die Datenbank konnte nicht heruntergeladen werden: %s','The downloaded database was empty.'=>'Die heruntergeladene Datenbank war leer.','The downloaded database could not be unpacked.'=>'Die heruntergeladene Datenbank konnte nicht entpackt werden.','Could not create the database directory.'=>'Das Datenbankverzeichnis konnte nicht erstellt werden.','Could not write the database file.'=>'Die Datenbankdatei konnte nicht geschrieben werden.','That does not look like a service account key file. It should contain client_email and private_key.'=>'Das sieht nicht nach einer Dienstkonto-Schlüsseldatei aus. Sie sollte client_email und private_key enthalten.','This server is missing the OpenSSL functions needed to authenticate with Google.'=>'Diesem Server fehlen die OpenSSL-Funktionen, die für die Authentifizierung bei Google nötig sind.','Could not sign the request with that key. Check the key file was pasted whole.'=>'Die Anfrage ließ sich mit diesem Schlüssel nicht signieren. Prüfen, ob die Schlüsseldatei vollständig eingefügt wurde.','Google would not issue an access token for that key.'=>'Google hat für diesen Schlüssel kein Zugriffstoken ausgestellt.','The job that records visits is not scheduled'=>'Der Job, der Besuche aufzeichnet, ist nicht geplant','Visits are being written to disk but nothing is moving them into your reports. Deactivating and reactivating the plugin will restore it.'=>'Besuche werden auf die Festplatte geschrieben, aber nichts überträgt sie in deine Berichte. Deaktivieren und erneutes Aktivieren des Plugins stellt das wieder her.','The recording job is scheduled'=>'Der Aufzeichnungsjob ist geplant','WordPress cron is disabled on this site, which is normal on managed hosting: the host runs it externally instead. Recording depends on that continuing to run.'=>'WordPress-Cron ist auf dieser Website deaktiviert, was bei Managed Hosting normal ist: Der Host führt es stattdessen extern aus. Die Aufzeichnung hängt davon ab, dass das weiterläuft.','Visits have not been recorded yet'=>'Es wurden noch keine Besuche aufgezeichnet','This is expected on a new install. If it persists for more than a few minutes, the recording job is not running.'=>'Das ist bei einer neuen Installation normal. Hält es länger als ein paar Minuten an, läuft der Aufzeichnungsjob nicht.','Visits stopped being recorded'=>'Die Aufzeichnung von Besuchen ist gestoppt','The last successful run was %s ago, and it should run every minute. Anything since then is still on disk and will be counted once this clears.'=>'Der letzte erfolgreiche Lauf war vor %s, dabei sollte er jede Minute laufen. Alles seitdem liegt noch auf der Festplatte und wird gezählt, sobald das Problem behoben ist.','Visits are being recorded'=>'Besuche werden aufgezeichnet','Last run %s ago.'=>'Letzter Lauf vor %s.','The database is refusing writes'=>'Die Datenbank verweigert Schreibvorgänge','%1$s. %2$d attempts have failed. The database reported: %3$s'=>'%1$s. %2$d Versuche sind fehlgeschlagen. Die Datenbank meldete: %3$s','no detail recorded'=>'keine Details aufgezeichnet','Some visits could not be saved'=>'Einige Besuche ließen sich nicht speichern','%d batch was set aside after repeated database errors. The visits are still on disk and can be replayed once the cause is fixed.'=>'%d Batch wurde nach wiederholten Datenbankfehlern zurückgestellt. Die Besuche liegen noch auf der Festplatte und können erneut verarbeitet werden, sobald die Ursache behoben ist.' . "\0" . '%d Batches wurden nach wiederholten Datenbankfehlern zurückgestellt. Die Besuche liegen noch auf der Festplatte und können erneut verarbeitet werden, sobald die Ursache behoben ist.','Visits are piling up without being saved'=>'Besuche stauen sich auf, ohne gespeichert zu werden','%1$s is waiting on disk, the oldest of it from %2$s ago. Visits are being captured but are not reaching your reports.'=>'%1$s wartet auf der Festplatte, das älteste davon seit %2$s. Besuche werden erfasst, erreichen aber nicht deine Berichte.','The data folder is missing'=>'Der Datenordner fehlt','Visits cannot be captured at all until it can be created inside wp-content/uploads.'=>'Besuche können erst erfasst werden, wenn er innerhalb von wp-content/uploads angelegt werden kann.','The data folder is not writable'=>'Der Datenordner ist nicht beschreibbar','Visits are being discarded as they arrive. Check the folder permissions inside wp-content/uploads.'=>'Besuche werden beim Eintreffen verworfen. Die Ordnerberechtigungen innerhalb von wp-content/uploads prüfen.','The data folder is writable'=>'Der Datenordner ist beschreibbar','The reporting tables are missing'=>'Die Berichtstabellen fehlen','Deactivating and reactivating the plugin will create them.'=>'Deaktivieren und erneutes Aktivieren des Plugins legt sie an.','No visits recorded yet'=>'Noch keine Besuche aufgezeichnet','Expected on a new install, or on a site with no traffic since the plugin was activated.'=>'Normal bei einer neuen Installation oder einer Website ohne Traffic seit der Aktivierung des Plugins.','Nothing has been recorded for a while'=>'Seit einer Weile wurde nichts aufgezeichnet','The most recent day with any data is %s. On a site with regular traffic this means recording has stopped.'=>'Der letzte Tag mit Daten ist %s. Bei einer Website mit regelmäßigem Traffic bedeutet das, dass die Aufzeichnung gestoppt ist.','Reports are up to date'=>'Berichte sind aktuell','Most recent data: %s.'=>'Neueste Daten: %s.','Vireo Analytics is recording visits'=>'Vireo Analytics zeichnet Besuche auf','Analytics'=>'Analytics','The recording job is scheduled, ran recently, and your reports are up to date.'=>'Der Aufzeichnungsjob ist geplant, lief vor Kurzem, und deine Berichte sind aktuell.','Vireo Analytics has stopped recording visits'=>'Vireo Analytics hat die Aufzeichnung von Besuchen gestoppt','Vireo Analytics is recording, with something worth checking'=>'Vireo Analytics zeichnet auf, aber etwas ist einen Blick wert','Whether visits are currently being captured and written to the database.'=>'Ob Besuche derzeit erfasst und in die Datenbank geschrieben werden.','“%1$s” gained the most, %2$s more view than the week before.'=>'„%1$s“ legte am stärksten zu, %2$s Aufruf mehr als in der Vorwoche.' . "\0" . '„%1$s“ legte am stärksten zu, %2$s Aufrufe mehr als in der Vorwoche.','%1$s sent visitors for the first time: %2$s views.'=>'%1$s hat zum ersten Mal Besucher geschickt: %2$s Aufrufe.','Your best week so far: %1$s pageviews, ahead of the previous best of %2$s.'=>'Deine bisher beste Woche: %1$s Seitenaufrufe, mehr als die bisherige Bestmarke von %2$s.','The site passed %s pageviews in total.'=>'Die Website hat insgesamt %s Seitenaufrufe überschritten.','%1$s passed %2$s views.'=>'%1$s hat %2$s Aufrufe überschritten.','%1$s was the busiest day, with %2$s view.'=>'%1$s war der Tag mit dem meisten Traffic, mit %2$s Aufruf.' . "\0" . '%1$s war der Tag mit dem meisten Traffic, mit %2$s Aufrufen.','Import from Koko Analytics'=>'Aus Koko Analytics importieren','Import from Jetpack Stats'=>'Aus Jetpack Stats importieren','Import from Google Analytics 4'=>'Import aus Google Analytics 4','Import from Plausible Analytics'=>'Import aus Plausible Analytics','Restore a Vireo Analytics backup'=>'Vireo-Analytics-Backup wiederherstellen','Import from %s'=>'Aus %s importieren','Unknown importer.'=>'Unbekannter Importer.','Replacing deletes everything Vireo Analytics has recorded here before loading the file. Tick the box to confirm, or choose Merge.'=>'Beim Ersetzen werden alle bisher von Vireo Analytics hier erfassten Daten gelöscht, bevor die Datei geladen wird. Setze das Häkchen zur Bestätigung oder wähle Zusammenführen.','Choose the backup file to begin.'=>'Wähle die Backup-Datei aus, um zu beginnen.','The saved key has been removed.'=>'Der gespeicherte Schlüssel wurde entfernt.','That key file could not be read. Paste the whole JSON file, including the private key.'=>'Diese Schlüsseldatei ließ sich nicht lesen. Die komplette JSON-Datei einfügen, einschließlich des privaten Schlüssels.','Paste the service account key file to begin.'=>'Die Dienstkonto-Schlüsseldatei einfügen, um zu beginnen.','Enter the numeric GA4 property ID.'=>'Die numerische GA4-Property-ID eingeben.','Choose a start date on or before the end date.'=>'Ein Startdatum vor oder am Enddatum wählen.','You have already imported Google Analytics data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Du hast bereits Google-Analytics-Daten für %s importiert. Ein erneuter Import addiert diese Zahlen zu den bereits gespeicherten, und das lässt sich nicht rückgängig machen. Den Zeitraum auf das Fehlende eingrenzen oder das Kästchen aktivieren, um trotzdem zu importieren.','Dates must be in YYYY-MM-DD format.'=>'Datumsangaben müssen im Format YYYY-MM-DD vorliegen.','Choose the export file from Plausible to begin.'=>'Wähle die Exportdatei von Plausible aus, um zu beginnen.','You have already imported Plausible data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Du hast bereits Plausible-Daten für %s importiert. Ein erneuter Import addiert diese Zahlen zu den bereits gespeicherten und lässt sich nicht rückgängig machen. Grenze den Zeitraum auf das ein, was fehlt, oder setze das Häkchen, um trotzdem zu importieren.','All fields are required.'=>'Alle Felder sind erforderlich.','Invalid Blog URI.'=>'Ungültige Blog-URI.','You have already imported Jetpack Stats covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Du hast bereits Jetpack-Stats-Daten für %s importiert. Ein erneuter Import addiert diese Zahlen zu den bereits gespeicherten und lässt sich nicht rückgängig machen. Grenze den Zeitraum auf das ein, was fehlt, oder setze das Häkchen, um trotzdem zu importieren.','This import screen is out of date. Reload it and start the import again.'=>'Dieser Importbildschirm ist veraltet. Lade ihn neu und starte den Import erneut.','%s has already been imported. Running it again would count the same history twice, so it needs confirming first. Reload the page to see what was imported.'=>'%s wurde bereits importiert. Ein erneuter Durchlauf würde denselben Verlauf doppelt zählen, deshalb ist zuerst eine Bestätigung nötig. Lade die Seite neu, um zu sehen, was importiert wurde.','Imported on %1$s at %2$s: %3$s day of history, %4$s to %5$s, %6$s pageviews.'=>'Importiert am %1$s um %2$s: %3$s Tag Verlauf, %4$s bis %5$s, %6$s Seitenaufrufe.' . "\0" . 'Importiert am %1$s um %2$s: %3$s Tage Verlauf, %4$s bis %5$s, %6$s Seitenaufrufe.','Imported on %1$s at %2$s, covering %3$s to %4$s.'=>'Importiert am %1$s um %2$s, Zeitraum: %3$s bis %4$s.','Imported on %1$s at %2$s.'=>'Importiert am %1$s um %2$s.','everything available'=>'alles Verfügbare','Collecting data. Your first pageviews appear within a minute; trends need a day to compare against.'=>'Daten werden gesammelt. Die ersten Seitenaufrufe erscheinen innerhalb einer Minute, Trends brauchen einen Tag zum Vergleich.','Collecting data, %s view so far. Trends appear once there is a prior day to compare against.'=>'Daten werden erfasst, bisher %s Aufruf. Trends erscheinen, sobald ein Vortag zum Vergleich vorliegt.' . "\0" . 'Daten werden erfasst, bisher %s Aufrufe. Trends erscheinen, sobald ein Vortag zum Vergleich vorliegt.','%1$s Mostly %2$s.'=>'%1$s Meist %2$s.','Steady, %1$s view, in line with the prior period. Top: %2$s.'=>'Stabil, %1$s Aufruf, auf dem Niveau des Vorzeitraums. Top: %2$s.' . "\0" . 'Stabil, %1$s Aufrufe, auf dem Niveau des Vorzeitraums. Top: %2$s.','Steady, %s view, in line with the prior period.'=>'Stabil, %s Aufruf, auf dem Niveau des Vorzeitraums.' . "\0" . 'Stabil, %s Aufrufe, auf dem Niveau des Vorzeitraums.','Source #%d'=>'Quelle #%d','That tool cannot be run on a child site.'=>'Dieses Tool kann nicht auf einer untergeordneten Website ausgeführt werden.','This site does not have that tool.'=>'Diese Website hat dieses Tool nicht.','Only read-only tools can be run on a child site.'=>'Auf einer untergeordneten Website können nur schreibgeschützte Tools ausgeführt werden.','The tool input is too large.'=>'Die Tool-Eingabe ist zu groß.','The tool input must be a JSON object.'=>'Die Tool-Eingabe muss ein JSON-Objekt sein.','Read-only site analytics: traffic, top content, where visitors came from, Google searches, AI assistant traffic, broken links, and what changed since the previous period.'=>'Schreibgeschützte Website-Analysen: Traffic, Top-Inhalte, Herkunft der Besucher, Google-Suchanfragen, Traffic von KI-Assistenten, defekte Links und Änderungen gegenüber dem vorherigen Zeitraum.','Revenue, which pages and sources drive sales, campaigns, funnels and real-time visitors need Vireo Pro: https://vireowp.com/pricing/'=>'Umsatz, welche Seiten und Quellen Verkäufe bringen, Kampagnen, Funnels und Besucher in Echtzeit erfordern Vireo Pro: https://vireowp.com/pricing/','You do not have permission to access this page.'=>'Sie haben keine Berechtigung, auf diese Seite zuzugreifen.','That does not look like a Google API key. It is a single line of letters, numbers, dashes and underscores, usually starting with AIza.'=>'Das sieht nicht nach einem Google-API-Schlüssel aus. Er besteht aus einer einzigen Zeile mit Buchstaben, Zahlen, Bindestrichen und Unterstrichen und beginnt meist mit AIza.','That is not a page address PageSpeed can test.'=>'Das ist keine Seitenadresse, die PageSpeed testen kann.','Only pages on this site can be tested.'=>'Es können nur Seiten dieser Website getestet werden.','PageSpeed can only test pages anyone can open. Publish this post first.'=>'PageSpeed kann nur Seiten testen, die jeder öffnen kann. Veröffentliche diesen Beitrag zuerst.','PageSpeed tests need a Google API key. An administrator can add one under Settings, Search Console & API.'=>'Für PageSpeed-Tests ist ein Google-API-Schlüssel nötig. Ein Administrator kann ihn unter Einstellungen, Search Console & API hinzufügen.','A test of this page is already running. Its result shows here when it finishes.'=>'Ein Test dieser Seite läuft bereits. Das Ergebnis erscheint hier, sobald er abgeschlossen ist.','Google did not answer within a minute. Slow pages can take that long. Try again.'=>'Google hat nicht innerhalb einer Minute geantwortet. Langsame Seiten können so lange brauchen. Versuche es erneut.','Could not reach Google: %s'=>'Google war nicht erreichbar: %s','PageSpeed runs on Google\'s servers, which cannot reach a site that is only on your computer or private network.'=>'PageSpeed läuft auf den Servern von Google, die eine Website, die nur auf deinem Computer oder in deinem privaten Netzwerk liegt, nicht erreichen können.','Google\'s limit for PageSpeed tests on this API key is used up for now. Try again later, or raise the quota in Google Cloud.'=>'Das Limit von Google für PageSpeed-Tests mit diesem API-Schlüssel ist vorerst aufgebraucht. Versuche es später erneut oder erhöhe das Kontingent in Google Cloud.','Google rejected the API key. Check it under Settings, Search Console & API.'=>'Google hat den API-Schlüssel abgelehnt. Prüfe ihn unter Einstellungen, Search Console & API.','Google refused the request. Check that the PageSpeed Insights API is enabled in the key\'s Google Cloud project and that the key\'s restrictions allow it.'=>'Google hat die Anfrage abgelehnt. Prüfe, ob die PageSpeed Insights API im Google-Cloud-Projekt des Schlüssels aktiviert ist und ob die Einschränkungen des Schlüssels sie zulassen.','Google\'s test could not load this page. Check that it is public and opens for logged-out visitors.'=>'Der Test von Google konnte diese Seite nicht laden. Prüfe, ob sie öffentlich ist und sich für nicht angemeldete Besucher öffnen lässt.','PageSpeed Insights sent back a result this version of Vireo cannot read.'=>'PageSpeed Insights hat ein Ergebnis zurückgeschickt, das diese Version von Vireo nicht lesen kann.','PageSpeed Insights returned an error (HTTP %d). Try again in a few minutes.'=>'PageSpeed Insights hat einen Fehler zurückgegeben (HTTP %d). Versuche es in ein paar Minuten erneut.','Blocking time'=>'Blockierzeit','First content'=>'Erster Inhalt','The lab stand-in for response to clicks. A test cannot click, so it measures how long the page was too busy to respond.'=>'Der Labor-Ersatz für die Reaktion auf Klicks. Ein Test kann nicht klicken, deshalb misst er, wie lange die Seite zu beschäftigt war, um zu reagieren.','How long until anything appeared.'=>'Wie lange es dauerte, bis etwas erschien.','Up to %s faster'=>'Bis zu %s schneller','Less layout shift'=>'Weniger Layout-Verschiebung','You are not allowed to run page tests.'=>'Du darfst keine Seitentests ausführen.','Popular posts (Vireo)'=>'Beliebte Beiträge (Vireo)','Your most viewed posts, from Vireo Analytics.'=>'Deine meistaufgerufenen Beiträge, von Vireo Analytics.','Popular posts'=>'Beliebte Beiträge','Last 7 days'=>'Letzte 7 Tage','Last 30 days'=>'Letzte 30 Tage','Last 90 days'=>'Letzte 90 Tage','All time'=>'Gesamter Zeitraum','Title:'=>'Titel:','Number of posts:'=>'Anzahl der Beiträge:','Period:'=>'Zeitraum:','Post types:'=>'Beitragstypen:','Display:'=>'Anzeige:','List'=>'Liste','List with featured images'=>'Liste mit Beitragsbildern','Show view counts'=>'Aufrufzahlen anzeigen','Leave out the post being viewed'=>'Aktuell angezeigten Beitrag ausblenden','%s view'=>'%s Aufruf' . "\0" . '%s Aufrufe','No popular posts yet. They appear here once Vireo has recorded views for published posts in this period.'=>'Noch keine beliebten Beiträge. Sie erscheinen hier, sobald Vireo in diesem Zeitraum Aufrufe für veröffentlichte Beiträge erfasst hat.','Views (30d)'=>'Aufrufe (30 T.)','%s in 30 days'=>'%s in 30 Tagen','Post stats · %s'=>'Beitragsstatistik · %s','Referrer not specified.'=>'Verweisquelle nicht angegeben.','Referrer · %s'=>'Verweisquelle · %s','Invalid start or end date.'=>'Ungültiges Start- oder Enddatum.','end must be on or after start.'=>'„end“ muss am oder nach „start“ liegen.','Goal not found.'=>'Ziel nicht gefunden.','180 days'=>'180 Tage','1 year'=>'1 Jahr','2 years'=>'2 Jahre','5 years'=>'5 Jahre','Never purge'=>'Nie löschen','Give the view a name.'=>'Gib der Ansicht einen Namen.','You can keep up to %d saved views. Delete one to save another.'=>'Du kannst bis zu %d gespeicherte Ansichten behalten. Lösche eine, um eine weitere zu speichern.','Enter the property exactly as Search Console shows it, either a URL or sc-domain:example.com.'=>'Die Property genau so eingeben, wie Search Console sie zeigt, entweder als URL oder als sc-domain:example.com.','Search Console is not connected yet.'=>'Search Console ist noch nicht verbunden.','Could not store the data for %s. Nothing was lost; run the sync again.'=>'Die Daten für %s ließen sich nicht speichern. Nichts ist verloren gegangen, die Synchronisierung erneut ausführen.','Google refused the request. Check the service account has access to this Search Console property.'=>'Google hat die Anfrage abgelehnt. Prüfen, ob das Dienstkonto Zugriff auf diese Search-Console-Property hat.','Search Console has no property with that address. Copy it exactly as it appears there.'=>'Search Console hat keine Property mit dieser Adresse. Sie genau so kopieren, wie sie dort erscheint.','Search Console returned an unexpected response (HTTP %d).'=>'Search Console hat eine unerwartete Antwort geliefert (HTTP %d).','Search Console returned a response we could not read.'=>'Search Console hat eine Antwort geliefert, die sich nicht lesen ließ.','General'=>'Allgemein','Tracking'=>'Tracking','Email digest'=>'E-Mail-Zusammenfassung','Search Console & API'=>'Search Console & API','Import & export'=>'Import & Export','Vireo Analytics Settings'=>'Vireo Analytics – Einstellungen','Settings'=>'Einstellungen','Settings saved.'=>'Einstellungen gespeichert.','Vireo Analytics:'=>'Vireo Analytics:','Geo-location database is missing. Countries will show as unknown until you install it.'=>'Die Geolokalisierungs-Datenbank fehlt. Länder werden als unbekannt angezeigt, bis Sie sie installieren.','Setup instructions'=>'Einrichtungsanleitung','Nothing was removed. Type the site\'s name exactly as shown to confirm.'=>'Es wurde nichts entfernt. Gib den Namen der Website genau wie angezeigt ein, um zu bestätigen.','Filtered as bot.'=>'Als Bot gefiltert.','Empty User-Agent is treated as a bot by Bot_Filter::is_bot_request.'=>'Ein leerer User-Agent wird von Bot_Filter::is_bot_request als Bot behandelt.','Filtered as bot. This request would NOT be tracked.'=>'Als Bot gefiltert. Diese Anfrage würde NICHT erfasst.','Would be tracked. This request passes the bot filter.'=>'Würde erfasst. Diese Anfrage passiert den Bot-Filter.','Matched the bot-UA pattern: %s'=>'Stimmt mit dem Bot-UA-Muster überein: %s','Matched via heuristic (e.g. empty UA) rather than the UA regex.'=>'Übereinstimmung über eine Heuristik (z. B. leerer UA) statt über die UA-Regex.','No bot-UA pattern matched, and no Cloudflare bot signals would fire for a typical request.'=>'Kein Bot-UA-Muster stimmte überein, und für eine typische Anfrage würden keine Cloudflare-Bot-Signale ausgelöst.','The front-end address was not saved. Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Die Front-End-Adresse wurde nicht gespeichert. Gib die vollständige Adresse der Website ein, beginnend mit http:// oder https://, zum Beispiel https://www.example.com.','Give the site a name.'=>'Gib der Website einen Namen.','Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Gib die vollständige Adresse der Website ein, beginnend mit http:// oder https://, zum Beispiel https://www.example.com.','This install has reached its number of connected sites.'=>'Diese Installation hat die Anzahl der erlaubten verbundenen Websites erreicht.','That address is already connected.'=>'Diese Adresse ist bereits verbunden.','That address is set as the headless front end. A site is either the front end for this WordPress site or a connected site with its own numbers, not both.'=>'Diese Adresse ist als Headless-Frontend festgelegt. Eine Website ist entweder das Frontend dieser WordPress-Website oder eine verbundene Website mit eigenen Zahlen, nicht beides.','That is this site\'s own address. Its pages are already counted.'=>'Das ist die eigene Adresse dieser Website. Ihre Seiten werden bereits gezählt.','%ss'=>'%ss','%sms'=>'%sms','Load time'=>'Ladezeit','Response to clicks'=>'Reaktion auf Klicks','Layout shift'=>'Layoutverschiebung','Good'=>'Gut','Needs work'=>'Verbesserungswürdig','Poor'=>'Schlecht','How long until the main content appeared.'=>'Wie lange es dauert, bis der Hauptinhalt erscheint.','How long the page took to respond when someone interacted with it.'=>'Wie lange die Seite braucht, um auf eine Interaktion zu reagieren.','How much the page moved around while it loaded.'=>'Wie stark sich die Seite beim Laden verschoben hat.','%1$s to %2$s'=>'%1$s bis %2$s','%1$s: imported from %2$s.'=>'%1$s: aus %2$s importiert.','%1$s: partly imported from %2$s, partly counted by Vireo Analytics.'=>'%1$s: teilweise aus %2$s importiert, teilweise von Vireo Analytics erfasst.','%s: counted by Vireo Analytics.'=>'%s: von Vireo Analytics erfasst.','%1$s in %2$s so far'=>'%1$s in %2$s bisher','%1$s in %2$s'=>'%1$s in %2$s','%s pageview.'=>'%s Seitenaufruf.' . "\0" . '%s Seitenaufrufe.','%1$s pageviews, %2$s on the same stretch of %3$s.'=>'%1$s Seitenaufrufe, %2$s im selben Abschnitt von %3$s.','%1$s pageviews, %2$s on %3$s.'=>'%1$s Seitenaufrufe, %2$s am %3$s.','Busiest month: %1$s. Busiest day: %2$s, with %3$s pageviews.'=>'Stärkster Monat: %1$s. Stärkster Tag: %2$s, mit %3$s Seitenaufrufen.','Top page: %1$s (%2$s pageviews).'=>'Top-Seite: %1$s (%2$s Seitenaufrufe).','Top referrer: %1$s (%2$s pageviews).'=>'Top-Referrer: %1$s (%2$s Seitenaufrufe).','Top country: %s.'=>'Top-Land: %s.','Includes history imported from %s.'=>'Enthält aus %s importierten Verlauf.','Home page and archives (imported)'=>'Startseite und Archive (importiert)','Google app'=>'Google-App','short date with yearM j, Y'=>'j. M Y','short date without yearM j'=>'j. M','Today'=>'Heute','Yesterday'=>'Gestern','Last 7'=>'Letzte 7','Last 14'=>'Letzte 14','Last 30'=>'Letzte 30','Last 90'=>'Letzte 90','This month'=>'Dieser Monat','Last month'=>'Letzter Monat','YTD'=>'Lfd. Jahr','Not shown with these filters'=>'Mit diesen Filtern nicht verfügbar','Previous period'=>'Vorheriger Zeitraum','Same period last year'=>'Gleicher Zeitraum im Vorjahr','Device is %s'=>'Gerät ist %s','Country is %s'=>'Land ist %s','Source is %s'=>'Quelle ist %s','Referrer is %s'=>'Referrer ist %s','Page is %s'=>'Seite ist %s','Vireo keeps daily totals per dimension, so this cannot be combined with the filters already on.'=>'Vireo speichert Tagessummen pro Dimension, daher lässt sich das nicht mit den bereits aktiven Filtern kombinieren.','Site'=>'Website','This site'=>'Diese Website','Switch'=>'Wechseln','This link asked for a view that has expired, so the default range is shown instead. Dashboard links stop working after about a day. Pick a range below to carry on.'=>'Dieser Link hat eine Ansicht angefordert, die abgelaufen ist, daher wird stattdessen der Standardbereich angezeigt. Dashboard-Links funktionieren nur etwa einen Tag lang. Wählen Sie unten einen Bereich, um fortzufahren.','All devices'=>'Alle Geräte','All sources'=>'Alle Quellen','All countries'=>'Alle Länder','Filter:'=>'Filter:','Device'=>'Gerät','Country'=>'Land','Source'=>'Quelle','Apply'=>'Anwenden','Remove this filter'=>'Diesen Filter entfernen','Clear all'=>'Alle zurücksetzen','Saved views'=>'Gespeicherte Ansichten','Saved views…'=>'Gespeicherte Ansichten …','Forget view'=>'Ansicht vergessen','Save view'=>'Ansicht speichern','View name'=>'Name der Ansicht','Name this view'=>'Ansicht benennen','Save'=>'Speichern','Cancel'=>'Abbrechen','Clear the filters'=>'Filter zurücksetzen','Filters apply to the Overview tab.'=>'Die Filter gelten für den Tab „Übersicht“.','Date range'=>'Datumsbereich','Custom'=>'Benutzerdefiniert','Year in review'=>'Jahresrückblick','Print / Save as PDF'=>'Drucken / Als PDF speichern','Compare'=>'Vergleichen','Compare with'=>'Vergleichen mit','Start'=>'Start','End'=>'Ende','Move %s. Drag, or focus and use the arrow keys.'=>'%s verschieben. Ziehen oder fokussieren und die Pfeiltasten verwenden.','Reset layout'=>'Layout zurücksetzen','Report sections'=>'Berichtsbereiche','Loading the backup of %1$s, %2$s to %3$s, %4$s rows. %5$s'=>'Backup von %1$s wird geladen, %2$s bis %3$s, %4$s Zeilen. %5$s','Everything recorded here is deleted first.'=>'Alles, was hier erfasst wurde, wird zuerst gelöscht.','Days in the file replace the same days here; everything else is kept.'=>'Tage aus der Datei ersetzen dieselben Tage hier, alles andere bleibt erhalten.','Loads a file made with Download backup on another install, or on this one. Everything the reports are built from comes across: daily totals, pages, referrers, countries, devices, events, missing pages, bot traffic, Core Web Vitals, chart notes and the Search Console cache. Settings and connected sites are not in the file.'=>'Lädt eine Datei, die mit „Backup herunterladen“ auf einer anderen oder auf dieser Installation erstellt wurde. Alles, woraus die Berichte aufgebaut sind, wird übernommen: Tageswerte, Seiten, Referrer, Länder, Geräte, Ereignisse, fehlende Seiten, Bot-Traffic, Core Web Vitals, Diagrammnotizen und der Search-Console-Cache. Einstellungen und verbundene Websites sind nicht in der Datei enthalten.','To make the file, open %s on the site you are copying from and use Download backup.'=>'Um die Datei zu erstellen, öffne %s auf der Website, von der du kopierst, und klicke auf „Backup herunterladen“.','Settings, Import & export'=>'Einstellungen, Import & Export','Backup file (.jsonl.gz or .jsonl)'=>'Backup-Datei (.jsonl.gz oder .jsonl)','Maximum upload size: %s.'=>'Maximale Upload-Größe: %s.','What to do with the numbers already here'=>'Was mit den bereits vorhandenen Zahlen passieren soll','Merge: days in the file replace the same days here, everything else is kept.'=>'Zusammenführen: Tage aus der Datei ersetzen dieselben Tage hier, alles andere bleibt erhalten.','Replace: delete everything recorded here first, so this site ends up holding exactly what the file holds.'=>'Ersetzen: Alles, was hier erfasst wurde, wird zuerst gelöscht, sodass diese Website danach genau den Inhalt der Datei enthält.','Replace deletes every report table on this site before loading the file, and that cannot be undone. Download a backup of this site first if there is anything here you might want back.'=>'Beim Ersetzen werden vor dem Laden der Datei alle Berichtstabellen dieser Website gelöscht, und das lässt sich nicht rückgängig machen. Lade zuerst ein Backup dieser Website herunter, falls du etwas davon noch brauchen könntest.','I understand that everything recorded here will be deleted.'=>'Mir ist klar, dass alles, was hier erfasst wurde, gelöscht wird.','Loading the same file twice gives the same numbers, so a restore that stopped partway can simply be run again.'=>'Wird dieselbe Datei zweimal geladen, ergeben sich dieselben Zahlen. Eine Wiederherstellung, die auf halbem Weg abgebrochen ist, kann also einfach erneut ausgeführt werden.','Earlier restores'=>'Frühere Wiederherstellungen','Restore'=>'Wiederherstellen','Restore progress'=>'Fortschritt der Wiederherstellung','View your reports'=>'Berichte ansehen','%s history imported'=>'%s-Verlauf importiert','It is part of your Vireo Analytics reports now. Imports cannot be undone, and running this one again would add the same history a second time.'=>'Er ist jetzt Teil deiner Vireo-Analytics-Berichte. Importe lassen sich nicht rückgängig machen, und ein erneuter Durchlauf würde denselben Verlauf ein zweites Mal hinzufügen.','Go to Plugins'=>'Zu den Plugins','This server is missing the OpenSSL functions needed to authenticate with Google. Ask your host to enable the PHP openssl extension.'=>'Diesem Server fehlen die OpenSSL-Funktionen, die für die Authentifizierung bei Google nötig sind. Den Hoster bitten, die PHP-Erweiterung openssl zu aktivieren.','Brings across daily pageviews and visitors, your pages, referrers, which pages each referrer sent readers to, countries, devices, outbound clicks, downloads, form submissions and your own custom events. Everything is stored in your own database, the same as traffic recorded from here on.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Referrer, die Seiten, auf die jeder Referrer Leser weitergeleitet hat, Länder, Geräte, ausgehende Klicks, Downloads, Formularübermittlungen und deine eigenen benutzerdefinierten Ereignisse. Alles wird in deiner eigenen Datenbank gespeichert, genau wie der Traffic, der ab jetzt erfasst wird.','How to get the key file'=>'So bekommst du die Schlüsseldatei','In Google Cloud Console'=>'In der Google Cloud Console','Create a project, or open one you already have.'=>'Ein Projekt erstellen oder ein vorhandenes öffnen.','Under APIs and services, enable the Google Analytics Data API. The plain Analytics API is a different one and will not work.'=>'Unter APIs und Dienste die Google Analytics Data API aktivieren. Die einfache Analytics API ist eine andere und funktioniert nicht.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com, and you need that address for the next part.'=>'Unter IAM und Verwaltung, dann Dienstkonten, ein Dienstkonto erstellen. Dessen Adresse endet auf .iam.gserviceaccount.com, und diese Adresse wird im nächsten Schritt gebraucht.','Open the service account, go to Keys, add a key, and choose JSON. The file downloads once and Google will not give it to you again.'=>'Das Dienstkonto öffnen, zu Schlüssel wechseln, einen Schlüssel hinzufügen und JSON wählen. Die Datei wird einmal heruntergeladen, Google stellt sie danach nicht erneut bereit.','In Google Analytics'=>'In Google Analytics','Open Admin, then Property access management, and add the service account address with Viewer access. Grant it on the property you want to import, not on the account.'=>'Verwaltung öffnen, dann Zugriffsverwaltung für Property, und die Dienstkonto-Adresse mit Betrachterzugriff hinzufügen. Auf der Property gewähren, die importiert werden soll, nicht auf dem Konto.','Your property ID is the number under Admin, then Property details. It is digits only, not the G- measurement ID.'=>'Die Property-ID ist die Zahl unter Verwaltung, dann Property-Details. Sie besteht nur aus Ziffern, nicht die Mess-ID, die mit G- beginnt.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below. The key stays in your database and is only used to ask Google for your own data. It is never sent anywhere else.'=>'Dann die heruntergeladene Datei in einem Texteditor öffnen und sie komplett, mit den geschweiften Klammern, in das Feld unten einfügen. Der Schlüssel bleibt in deiner Datenbank und wird nur verwendet, um Google nach deinen eigenen Daten zu fragen. Er wird nirgendwo sonst hin gesendet.','Service account key (JSON)'=>'Dienstkontoschlüssel (JSON)','A key is saved. Leave this empty to keep it.'=>'Ein Schlüssel ist gespeichert. Leer lassen, um ihn zu behalten.','Using %s. Grant that address Viewer access on the property.'=>'Verwendet %s. Dieser Adresse Betrachterzugriff auf die Property gewähren.','Property ID'=>'Property-ID','Start date'=>'Startdatum','End date'=>'Enddatum','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, narrow the range to what is missing rather than starting again from the beginning.'=>'Der Import derselben Daten zweimal addiert die Zahlen doppelt, und das lässt sich nicht rückgängig machen. Bricht ein Lauf mittendrin ab, den Zeitraum auf das Fehlende eingrenzen, statt von vorn zu beginnen.','Already imported'=>'Bereits importiert','Import these dates again anyway, adding to what is already stored.'=>'Diese Daten trotzdem erneut importieren, ergänzend zum bereits Gespeicherten.','Start import'=>'Import starten','Import progress'=>'Importfortschritt','Remove the saved key'=>'Den gespeicherten Schlüssel entfernen','The key is only needed while importing. Removing it does not affect data already brought across.'=>'Der Schlüssel wird nur während des Imports gebraucht. Ihn zu entfernen wirkt sich nicht auf bereits übertragene Daten aus.','No %s data found in this database. The plugin needs to have been installed on this site and collected some data before there is anything to bring across.'=>'In dieser Datenbank wurden keine Daten von %s gefunden. Das Plugin muss auf dieser Website installiert gewesen sein und Daten gesammelt haben, bevor es etwas zu übernehmen gibt.','Back to import & export'=>'Zurück zu Import & Export','Records found'=>'Gefundene Datensätze','What this does:'=>'Was passiert dabei:','Copies your history from %s into Vireo Analytics. The source data is read only and is never modified.'=>'Kopiert Ihren Verlauf aus %s in Vireo Analytics. Die Quelldaten werden nur gelesen und nie verändert.','Run it once.'=>'Nur einmal ausführen.','An import adds what it reads to what Vireo Analytics already holds, so a second run would count the same history twice. Imports cannot be undone.'=>'Ein Import fügt das Gelesene zu dem hinzu, was Vireo Analytics bereits gespeichert hat. Ein zweiter Durchlauf würde denselben Verlauf also doppelt zählen. Importe lassen sich nicht rückgängig machen.','Import again anyway'=>'Trotzdem erneut importieren','Only if Vireo Analytics no longer holds the history from %s, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Nur wenn Vireo Analytics den Verlauf von %s nicht mehr enthält, zum Beispiel nach einem Zurücksetzen der Daten. Andernfalls wird jeder oben importierte Tag doppelt gezählt, und es gibt keine Möglichkeit, das wieder zu entfernen.','I understand this adds the same history a second time.'=>'Mir ist klar, dass dadurch derselbe Verlauf ein zweites Mal hinzugefügt wird.','Import again'=>'Erneut importieren','You can deactivate %s whenever you are ready. Vireo Analytics is tracking on its own now.'=>'Du kannst %s deaktivieren, sobald du so weit bist. Vireo Analytics erfasst jetzt eigenständig.','Jetpack isn\'t active here, so the import uses your WordPress.com API key.'=>'Jetpack ist hier nicht aktiv, daher nutzt der Import deinen WordPress.com-API-Schlüssel.','Pulls daily pageviews and referrers from the Jetpack / WordPress.com stats API. Country and device data isn\'t available in this API — Vireo Analytics will start tracking those from installation onward.'=>'Ruft tägliche Seitenaufrufe und Verweisquellen aus der Jetpack-/WordPress.com-Statistik-API ab. Länder- und Gerätedaten sind über diese API nicht verfügbar – Vireo Analytics beginnt ab der Installation, diese zu erfassen.','Jetpack Stats has no visitor counts, so imported days show pageviews only.'=>'Jetpack Stats enthält keine Besucherzahlen, daher zeigen importierte Tage nur Seitenaufrufe.','WordPress.com API key'=>'WordPress.com-API-Schlüssel','A key is saved for this import — leave blank to reuse it'=>'Für diesen Import ist ein Schlüssel gespeichert – leer lassen, um ihn erneut zu verwenden','Find this under <strong>Jetpack → Settings → Security → Akismet</strong>, or in your WordPress.com account under <strong>Security → Application Passwords</strong>.'=>'Sie finden dies unter <strong>Jetpack → Einstellungen → Sicherheit → Akismet</strong> oder in Ihrem WordPress.com-Konto unter <strong>Sicherheit → Anwendungspasswörter</strong>.','Blog URI'=>'Blog-URI','The domain Jetpack is tracking. Usually your site\'s host.'=>'Die von Jetpack erfasste Domain. Üblicherweise der Host Ihrer Website.','Re-running is additive.'=>'Ein erneuter Durchlauf addiert die Daten.','Running the import over an overlapping date range will double-count those days.'=>'Wenn Sie den Import über einen sich überschneidenden Datumsbereich ausführen, werden diese Tage doppelt gezählt.','No Koko Analytics data found in this database. If you just activated Koko Analytics, let it collect some pageviews first and come back.'=>'In dieser Datenbank wurden keine Koko-Analytics-Daten gefunden. Wenn Sie Koko Analytics gerade erst aktiviert haben, lassen Sie es zunächst einige Seitenaufrufe sammeln und kommen Sie dann zurück.','Days of data'=>'Tage mit Daten','Copies Koko\'s daily rollups into Vireo Analytics\'s tables. Koko\'s data is not modified.'=>'Kopiert Kokos tägliche Zusammenfassungen in die Tabellen von Vireo Analytics. Die Daten von Koko werden nicht verändert.','Pageviews, visitors, pages and referrers come across. Countries, devices and events from Koko Analytics Pro are not imported.'=>'Seitenaufrufe, Besucher, Seiten und Referrer werden übernommen. Länder, Geräte und Ereignisse aus Koko Analytics Pro werden nicht importiert.','Only if Vireo Analytics no longer holds the history from Koko Analytics, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Nur wenn Vireo Analytics den Verlauf von Koko Analytics nicht mehr enthält, zum Beispiel nach einem Zurücksetzen der Daten. Andernfalls wird jeder oben importierte Tag doppelt gezählt, und es gibt keine Möglichkeit, das wieder zu entfernen.','You can deactivate Koko Analytics from the Plugins screen when you\'re ready. Vireo Analytics is tracking on its own now.'=>'Du kannst Koko Analytics im Bereich „Plugins“ deaktivieren, wenn du so weit bist. Vireo Analytics erfasst jetzt eigenständig.','Dismiss'=>'Ausblenden','Welcome to Vireo Analytics.'=>'Willkommen bei Vireo Analytics.','We found Koko Analytics here with %d day of data. Bring it across in one click, rather than starting at zero.'=>'Wir haben hier Koko Analytics mit %d Tag an Daten gefunden. Übernimm sie mit einem Klick, statt bei null anzufangen.' . "\0" . 'Wir haben hier Koko Analytics mit %d Tagen an Daten gefunden. Übernimm sie mit einem Klick, statt bei null anzufangen.','We found %s on this site. Import that history so your numbers do not start at zero. Your existing data is read only and is never changed.'=>'Wir haben %s auf dieser Website gefunden. Importieren Sie diesen Verlauf, damit Ihre Zahlen nicht bei null beginnen. Ihre vorhandenen Daten werden nur gelesen und nie verändert.','Start fresh'=>'Neu beginnen','Vireo Analytics has its own data from %1$s, so the import stops on %2$s. Days from %1$s on keep the counts Vireo recorded.'=>'Vireo Analytics hat ab dem %1$s eigene Daten, deshalb endet der Import am %2$s. Tage ab dem %1$s behalten die von Vireo erfassten Werte.','Also import %s onwards. Those days already hold what Vireo counted, so the imported numbers are added on top and the days are counted twice.'=>'Importiere auch alles ab dem %s. Für diese Tage liegen bereits Daten vor, die Vireo gezählt hat. Die importierten Zahlen werden daher addiert und die Tage doppelt gezählt.','daily visitors and pageviews'=>'tägliche Besucher und Seitenaufrufe','device types'=>'Gerätetypen','entry pages'=>'Einstiegsseiten','exit pages'=>'Ausstiegsseiten','browsers'=>'Browser','operating systems'=>'Betriebssysteme','goals and custom events'=>'Ziele und benutzerdefinierte Ereignisse','custom properties'=>'benutzerdefinierte Properties','referrers, which this export names without their addresses'=>'Verweisquellen, die in diesem Export ohne ihre Adressen aufgeführt sind','Importing %1$s to %2$s: %3$s.'=>'Import von %1$s bis %2$s: %3$s.','Not imported, because Vireo Analytics has nowhere to keep them: %s.'=>'Nicht importiert, weil Vireo Analytics dafür keinen Speicherplatz hat: %s.','Import another export'=>'Weiteren Export importieren','For an export covering dates not imported yet. Dates already imported are refused unless you confirm them below.'=>'Für einen Export mit Datumsangaben, die noch nicht importiert wurden. Bereits importierte Tage werden abgelehnt, sofern du sie unten nicht bestätigst.','Brings across daily pageviews and visitors, your pages, referrers, countries, device types, and goals and custom events from a Plausible export. Outbound link clicks, file downloads and form submissions become the same events Vireo Analytics records itself, and 404 events are listed under missing pages. Browsers and operating systems are not imported: Plausible exports them separately from device type, and Vireo Analytics stores the three together, so for imported days they show as Unknown.'=>'Übernimmt tägliche Seitenaufrufe und Besucher, deine Seiten, Referrer, Länder, Gerätetypen sowie Ziele und benutzerdefinierte Ereignisse aus einem Plausible-Export. Klicks auf ausgehende Links, Dateidownloads und Formularübermittlungen werden zu denselben Ereignissen, die Vireo Analytics selbst erfasst, und 404-Ereignisse werden unter den fehlenden Seiten aufgeführt. Browser und Betriebssysteme werden nicht importiert: Plausible exportiert sie getrennt vom Gerätetyp, und Vireo Analytics speichert alle drei zusammen, daher werden sie für importierte Tage als Unbekannt angezeigt.','How to get the export'=>'So erhältst du den Export','In Plausible, open the site, then Site settings, then Imports & Exports.'=>'Öffne in Plausible die Website, dann „Site settings“ und anschließend „Imports & Exports“.','Under Export data, start an export. Plausible emails a link to a zip file when it is ready.'=>'Starte unter „Export data“ einen Export. Sobald er fertig ist, schickt Plausible dir per E-Mail einen Link zu einer ZIP-Datei.','Download the zip and upload it here as it is. If you have already unzipped it, select the CSV files instead.'=>'Lade die ZIP-Datei herunter und lade sie unverändert hier hoch. Falls du sie bereits entpackt hast, wähle stattdessen die CSV-Dateien aus.','The file is read once and deleted. Nothing is sent to Plausible and no account details are needed.'=>'Die Datei wird einmal gelesen und anschließend gelöscht. Es werden keine Daten an Plausible gesendet und keine Kontodaten benötigt.','Plausible export (.zip or .csv files)'=>'Plausible-Export (.zip- oder .csv-Dateien)','Optional. Leave both empty to import every day in the export.'=>'Optional. Lass beide Felder leer, um alle Tage des Exports zu importieren.','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, set the dates to what is missing rather than starting again from the beginning.'=>'Wenn du dieselben Tage zweimal importierst, werden die Zahlen doppelt addiert. Das lässt sich nicht rückgängig machen. Wenn ein Import zwischendurch abbricht, setze die Daten auf den fehlenden Zeitraum, statt von vorn zu beginnen.','Analytics across the network'=>'Analytics im gesamten Netzwerk','Last %d day'=>'Letzter %d Tag' . "\0" . 'Letzte %d Tage','Refresh'=>'Aktualisieren','This network has more sites than one page can query. Showing the first %1$s of %2$s.'=>'Dieses Netzwerk hat mehr Websites, als eine Seite abfragen kann. Zeigt die ersten %1$s von %2$s.','No site on the network has recorded anything yet.'=>'Keine Website im Netzwerk hat bisher etwas aufgezeichnet.','%1$s and %2$s across %3$s, %4$s to %5$s.'=>'%1$s und %2$s aus %3$s, %4$s bis %5$s.','%s pageview'=>'%s Seitenaufruf' . "\0" . '%s Seitenaufrufe','%s visitor'=>'%s Besucher' . "\0" . '%s Besucher','%s site'=>'%s Website' . "\0" . '%s Websites','Open'=>'Öffnen','Totals are cached for fifteen minutes, since each one is a separate query against that site.'=>'Summen werden fünfzehn Minuten lang zwischengespeichert, da jede eine eigene Abfrage gegen die jeweilige Website ist.','Monday'=>'Montag','Tuesday'=>'Dienstag','Wednesday'=>'Mittwoch','Thursday'=>'Donnerstag','Friday'=>'Freitag','Saturday'=>'Samstag','Sunday'=>'Sonntag','WordPress handed the test email for %s to your server\'s mail system.'=>'WordPress hat die Test-E-Mail an %s an das Mailsystem Ihres Servers übergeben.','If it has not arrived within a few minutes, check your spam folder. If it is not there either, your host is not delivering mail sent from WordPress, which affects password resets and every other email the site sends. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Falls sie nach ein paar Minuten nicht angekommen ist, sehen Sie im Spam-Ordner nach. Ist sie auch dort nicht, stellt Ihr Host keine von WordPress gesendeten E-Mails zu. Das betrifft auch das Zurücksetzen von Passwörtern und jede andere E-Mail der Website. Ein SMTP-Plugin wie WP Mail SMTP oder FluentSMTP behebt das in der Regel.','WordPress could not send the test email to %s.'=>'WordPress konnte die Test-E-Mail an %s nicht senden.','The mail system said: %s'=>'Meldung des Mailsystems: %s','This is a problem with how the site sends mail, not with the digest. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Das Problem liegt daran, wie die Website E-Mails versendet, nicht an der Zusammenfassung. Ein SMTP-Plugin wie WP Mail SMTP oder FluentSMTP behebt das in der Regel.','Email reports class is not loaded.'=>'Die Klasse für E-Mail-Berichte ist nicht geladen.','Country database installed. Countries will resolve from now on.'=>'Länderdatenbank installiert. Länder werden von nun an aufgelöst.','The country database could not be installed.'=>'Die Länderdatenbank konnte nicht installiert werden.','Site connected. Paste its tag into the site and its visits will start showing on the dashboard.'=>'Website verbunden. Füge den Tag in die Website ein, dann erscheinen ihre Besuche im Dashboard.','Site removed, along with everything recorded for it.'=>'Website samt aller dafür erfassten Daten entfernt.','That did not work.'=>'Das hat nicht funktioniert.','%s stored day removed from the countries report.'=>'%s gespeicherter Tag aus dem Länderbericht entfernt.' . "\0" . '%s gespeicherte Tage aus dem Länderbericht entfernt.','Settings sections'=>'Einstellungsbereiche','Do not count'=>'Nicht zählen','Roles whose visits are not counted'=>'Rollen, deren Besuche nicht gezählt werden','Visits from people logged in with a ticked role are left out of every report. Administrators are ticked by default so your own browsing does not pollute the stats; tick editors, authors or shop managers to leave out the rest of the team.'=>'Besuche von angemeldeten Personen mit einer angehakten Rolle werden aus allen Berichten ausgeschlossen. Administratoren sind standardmäßig angehakt, damit dein eigenes Surfen die Statistiken nicht verfälscht. Hake Redakteure, Autoren oder Shop-Manager an, um auch den Rest des Teams auszuschließen.','Toolbar'=>'Werkzeugleiste','Show today\'s pageviews in the admin toolbar.'=>'Die heutigen Seitenaufrufe in der Admin-Werkzeugleiste anzeigen.','Data retention'=>'Datenaufbewahrung','Custom (%d day)'=>'Benutzerdefiniert (%d Tag)' . "\0" . 'Benutzerdefiniert (%d Tage)','Rows in daily rollup tables older than this are purged by a daily cron job.'=>'Zeilen in den täglichen Zusammenfassungstabellen, die älter als dieser Wert sind, werden durch einen täglichen Cron-Job gelöscht.','Current usage: %1$s MB across %2$d analytics table.'=>'Aktuelle Nutzung: %1$s MB in %2$d Analytics-Tabelle.' . "\0" . 'Aktuelle Nutzung: %1$s MB in %2$d Analytics-Tabellen.','Who can see the numbers'=>'Wer die Zahlen sehen kann','Roles with access'=>'Rollen mit Zugriff','Roles that can view analytics'=>'Rollen, die Analytics einsehen können','Administrator'=>'Administrator','(always)'=>'(immer)','Administrators can always read the dashboard. This cannot be changed.'=>'Administratoren können das Dashboard immer lesen. Das lässt sich nicht ändern.','Lets someone read the dashboard without making them an administrator. Changing settings, running imports and everything destructive still needs full administrator rights.'=>'Erlaubt jemandem, das Dashboard zu lesen, ohne ihn zum Administrator zu machen. Einstellungen ändern, Importe ausführen und alles Destruktive erfordert weiterhin volle Administratorrechte.','Headless front end'=>'Headless-Front-End','If this WordPress site is only the editor and another site (Astro, Next.js, anything else) shows the pages to readers, enter that site\'s address. Its pages can then send pageviews here, and each one is matched to the WordPress post it shows.'=>'Wenn diese WordPress-Website nur der Editor ist und eine andere Website (Astro, Next.js oder etwas anderes) die Seiten für Leser ausliefert, gib die Adresse dieser Website ein. Ihre Seiten können dann Seitenaufrufe hierher senden, und jeder Aufruf wird dem WordPress-Beitrag zugeordnet, den er anzeigt.','Front-end site address'=>'Adresse der Front-End-Website','The address readers see in their browser, including https://. One site; pageviews sent from any other address are refused. Leave empty if this WordPress site serves its own pages.'=>'Die Adresse, die Leser in ihrem Browser sehen, einschließlich https://. Eine Website; Seitenaufrufe, die von einer anderen Adresse gesendet werden, werden abgelehnt. Lass das Feld leer, wenn diese WordPress-Website ihre Seiten selbst ausliefert.','Add to the front end'=>'Zum Front-End hinzufügen','Paste this before </body> on every page. Pages that know their WordPress post can add <meta name="vireo:post-id" content="123">; for a site that changes pages without reloading, add data-spa="history" to the tag.'=>'Füge dies auf jeder Seite vor </body> ein. Seiten, die ihren WordPress-Beitrag kennen, können <meta name="vireo:post-id" content="123"> hinzufügen; bei einer Website, die Seiten ohne Neuladen wechselt, füge dem Tag data-spa="history" hinzu.','Pageviews are sent to %s. Pages are matched to posts by their path, so a front end that keeps the WordPress permalink structure needs nothing else; the vireo_headless_post_id filter maps anything that differs.'=>'Seitenaufrufe werden an %s gesendet. Seiten werden anhand ihres Pfads den Beiträgen zugeordnet. Ein Front-End, das die WordPress-Permalink-Struktur beibehält, braucht also nichts weiter; der Filter vireo_headless_post_id ordnet alles zu, was davon abweicht.','What this cannot see'=>'Was hier nicht erfasst wird','Crawlers and AI bots are counted when they request a page from this WordPress site. Requests they make to the front end never reach it, so the crawler figures on the dashboard cover WordPress only; your front-end host\'s logs have the rest.'=>'Crawler und KI-Bots werden gezählt, wenn sie eine Seite dieser WordPress-Website abrufen. Anfragen, die sie an das Front-End stellen, erreichen sie nie, daher decken die Crawler-Zahlen im Dashboard nur WordPress ab; die Logs deines Front-End-Hosts enthalten den Rest.','Connect Search Console for the front-end address, since that is the site Google indexes. Core Web Vitals are not collected from the front end in this version.'=>'Verbinde die Search Console für die Frontend-Adresse, denn das ist die Website, die Google indexiert. Core Web Vitals werden in dieser Version nicht aus dem Frontend erfasst.','Exclusions'=>'Ausschlüsse','Skip pageviews from known bots, your own IPs, or internal paths. Bot UAs are filtered automatically; these rules run on top.'=>'Seitenaufrufe von bekannten Bots, Ihren eigenen IPs oder internen Pfaden überspringen. Bot-UAs werden automatisch gefiltert; diese Regeln kommen zusätzlich hinzu.','Excluded IPs / CIDR'=>'Ausgeschlossene IPs / CIDR','One entry per line. IPv4, IPv6, and CIDR ranges are supported.'=>'Ein Eintrag pro Zeile. IPv4, IPv6 und CIDR-Bereiche werden unterstützt.','Excluded paths'=>'Ausgeschlossene Pfade','One path pattern per line. Use <code>*</code> for any chars except <code>/</code>, <code>**</code> for any chars.'=>'Ein Pfadmuster pro Zeile. Verwenden Sie <code>*</code> für beliebige Zeichen außer <code>/</code> und <code>**</code> für beliebige Zeichen.','Blocked referrers'=>'Blockierte Referrer','Sites whose visits are filtered like bots and hidden from reports. Known referrer spam is blocked already; these are the ones you added from a referrer row.'=>'Websites, deren Besuche wie Bots gefiltert und in den Berichten ausgeblendet werden. Bekannter Referrer-Spam ist bereits blockiert. Hier stehen die, die du aus einer Referrer-Zeile hinzugefügt hast.','Blocked hosts'=>'Blockierte Hosts','One host per line; subdomains are included. Remove a line to unblock it. Blocking stops counting from now on and hides earlier rows; nothing is deleted.'=>'Ein Host pro Zeile, Subdomains sind eingeschlossen. Entferne eine Zeile, um die Blockierung aufzuheben. Eine Blockierung stoppt das Zählen ab sofort und blendet frühere Einträge aus, es wird nichts gelöscht.','Geo-location'=>'Geolokalisierung','Countries'=>'Länder','Resolving'=>'Wird aufgelöst','Your host or CDN already tells us each visitor\'s country (it reported %s for this request), so countries resolve automatically. No database needed.'=>'Ihr Host oder CDN teilt uns das Land jedes Besuchers bereits mit (für diese Anfrage wurde %s gemeldet), daher werden Länder automatisch aufgelöst. Keine Datenbank erforderlich.','Installed'=>'Installiert','Country lookups run against the local database on this server.'=>'Länderabfragen erfolgen gegen die lokale Datenbank auf diesem Server.','Geolocation by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.'=>'Geolokalisierung durch <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.','Not resolving'=>'Wird nicht aufgelöst','Every visitor is recorded as unknown until a country source is available. The one-click database below fixes it.'=>'Jeder Besucher wird als unbekannt erfasst, bis eine Länderquelle verfügbar ist. Die Ein-Klick-Datenbank unten behebt das.','Download country database'=>'Länderdatenbank herunterladen','Free, no account, installed for you. Data by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).'=>'Kostenlos, kein Konto, für Sie installiert. Daten von <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).','Prefer MaxMind GeoLite2? (manual)'=>'Lieber MaxMind GeoLite2? (manuell)','Create a free account at <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> and generate a license key.'=>'Erstellen Sie ein kostenloses Konto unter <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> und erzeugen Sie einen Lizenzschlüssel.','Download <code>GeoLite2-Country.mmdb</code> (the Country edition is enough).'=>'Laden Sie <code>GeoLite2-Country.mmdb</code> herunter (die Country-Edition genügt).','Upload it to <code>%s/</code> on this server.'=>'Laden Sie sie nach <code>%s/</code> auf diesem Server hoch.','MaxMind requires an account and prohibits automatic downloads, which is why it is manual.'=>'MaxMind erfordert ein Konto und verbietet automatische Downloads, weshalb dies manuell erfolgt.','Excluded countries'=>'Ausgeschlossene Länder','One two-letter country code per line. Traffic from these countries is discarded instead of counted, the same as an excluded IP. Bots that announce themselves are already filtered; this is for the traffic that does not.'=>'Ein zweistelliger Ländercode pro Zeile. Traffic aus diesen Ländern wird verworfen statt gezählt, genau wie bei einer ausgeschlossenen IP. Bots, die sich zu erkennen geben, werden bereits gefiltert; das hier ist für den Traffic, der das nicht tut.','Needs the country to be known, so it requires either a host that resolves it or the database above.'=>'Setzt voraus, dass das Land bekannt ist, also entweder einen Host, der es auflöst, oder die Datenbank oben.','Excluding a country stops it being counted from now on. It does not remove what was counted before, so a report covering earlier dates still shows it.'=>'Wenn Sie ein Land ausschließen, wird es ab jetzt nicht mehr gezählt. Bereits Gezähltes bleibt erhalten, ein Bericht über frühere Zeiträume zeigt es also weiterhin.','Remove stored data for %s'=>'Gespeicherte Daten für %s entfernen','Clears them from the countries report. Pageview and visitor totals keep those visits, because nothing else records which country a visit came from.'=>'Entfernt sie aus dem Länderbericht. Die Summen der Seitenaufrufe und Besucher behalten diese Besuche, weil nirgends sonst erfasst wird, aus welchem Land ein Besuch kam.','Auto-events'=>'Automatische Ereignisse','Record common clicks and form sends as events, with no code to add. Each one shows up on the Campaigns tab.'=>'Häufige Klicks und Formularversand als Ereignisse erfassen, ganz ohne Code. Sie erscheinen im Tab Kampagnen.','File downloads'=>'Datei-Downloads','Record clicks on links to files (PDF, ZIP, DOC, MP3, MP4, etc.).'=>'Klicks auf Links zu Dateien (PDF, ZIP, DOC, MP3, MP4 usw.) erfassen.','Fires a "download" event with the filename as the value.'=>'Löst ein „download“-Ereignis mit dem Dateinamen als Wert aus.','Form submissions'=>'Formularübermittlungen','Record every form submit.'=>'Jede Formularübermittlung erfassen.','Fires a "form_submit" event with the form id, name, or action URL.'=>'Löst ein „form_submit“-Ereignis mit der Formular-ID, dem Namen oder der Action-URL aus.','Email links'=>'E-Mail-Links','Record clicks on mailto: links.'=>'Klicks auf mailto:-Links erfassen.','Only the part after the @ is kept, so no email address is stored.'=>'Nur der Teil nach dem @ wird gespeichert, also keine E-Mail-Adresse.','Phone links'=>'Telefon-Links','Record clicks on tel: links.'=>'Klicks auf tel:-Links erfassen.','Outbound links'=>'Ausgehende Links','Record clicks on links to external domains.'=>'Klicks auf Links zu externen Domains erfassen.','Pro records outbound clicks with more detail, so this option is off to avoid counting each click twice.'=>'Pro erfasst ausgehende Klicks ausführlicher. Diese Option ist deshalb aus, damit kein Klick doppelt zählt.','Fires an "outbound" event with the external host as the value.'=>'Löst ein „outbound“-Ereignis mit dem externen Host als Wert aus.','The last day, week or month in one email: top pages, referrers and countries. It\'s built on your server and sent with your site\'s own mail.'=>'Der letzte Tag, die letzte Woche oder der letzte Monat in einer E-Mail: Top-Seiten, Referrer und Länder. Sie wird auf deinem Server erstellt und mit dem eigenen Mailversand deiner Website verschickt.','Enable'=>'Aktivieren','Send the digest'=>'Zusammenfassung senden','Frequency'=>'Häufigkeit','Every morning, covering the day before.'=>'Jeden Morgen für den Vortag.','Once a week, covering the last seven full days.'=>'Einmal pro Woche für die letzten sieben vollen Tage.','On the first of each month, covering the month before.'=>'Am Ersten jedes Monats für den Vormonat.','Recipients'=>'Empfänger','One email per line. Leave blank to fall back to the site admin (%s).'=>'Eine E-Mail-Adresse pro Zeile. Leer lassen, um auf den Website-Administrator (%s) zurückzugreifen.','When'=>'Wann','Hour'=>'Stunde','Site timezone (%s).'=>'Zeitzone der Website (%s).','Save settings'=>'Einstellungen speichern','Connected sites'=>'Verbundene Websites','Count visits to other sites you run, whether or not they use WordPress: a static site, a docs site, a landing page. Each connected site keeps its own numbers, and the dashboard switches between them. Unlike the headless front end above, its pages are not matched to posts here.'=>'Zähle Besuche auf anderen Websites, die du betreibst, ob mit oder ohne WordPress: eine statische Website, eine Dokumentations-Website, eine Landingpage. Jede verbundene Website behält ihre eigenen Zahlen, und das Dashboard wechselt zwischen ihnen. Anders als beim Headless-Frontend oben werden ihre Seiten hier nicht Beiträgen zugeordnet.','Paste this before </body> on every page of the site. The second line collects Core Web Vitals and can be left out. For a site that changes pages without reloading, add data-spa="history" to the first tag.'=>'Füge das vor </body> auf jeder Seite der Website ein. Die zweite Zeile erfasst Core Web Vitals und kann weggelassen werden. Füge bei einer Website, die Seiten ohne Neuladen wechselt, data-spa="history" zum ersten Tag hinzu.','Pageviews are accepted only when the browser sends them from %s, so the tag records nothing if it is pasted anywhere else.'=>'Seitenaufrufe werden nur akzeptiert, wenn der Browser sie von %s sendet. Der Tag erfasst also nichts, wenn er anderswo eingefügt wird.','Remove this site…'=>'Diese Website entfernen…','This deletes every number recorded for %s. There is no undo. Type the site\'s name to confirm.'=>'Dadurch werden alle für %s erfassten Zahlen gelöscht. Das lässt sich nicht rückgängig machen. Gib zur Bestätigung den Namen der Website ein.','Site name'=>'Name der Website','Remove site and its data'=>'Website und ihre Daten entfernen','Keep it'=>'Behalten','Docs site'=>'Dokumentations-Website','Site address'=>'Adresse der Website','The address readers see in their browser, including https://. Visits sent from any other address are refused.'=>'Die Adresse, die Leser in ihrem Browser sehen, einschließlich https://. Besuche, die von einer anderen Adresse gesendet werden, werden abgelehnt.','Connect site'=>'Website verbinden','This install allows %d connected site.'=>'Diese Installation erlaubt %d verbundene Website.' . "\0" . 'Diese Installation erlaubt %d verbundene Websites.','Bot filter test'=>'Bot-Filter-Test','Paste a User-Agent to see whether Vireo Analytics would filter it as a bot. Useful when debugging why a visitor (or monitoring tool) isn\'t showing up in stats.'=>'Fügen Sie einen User-Agent ein, um zu sehen, ob Vireo Analytics ihn als Bot filtern würde. Nützlich bei der Fehlersuche, warum ein Besucher (oder ein Monitoring-Tool) nicht in den Statistiken erscheint.','User-Agent'=>'User-Agent','Test User-Agent'=>'User-Agent testen','Test email'=>'Test-E-Mail','Sends the digest for the last finished period to %s right now (bypasses the schedule).'=>'Sendet die Zusammenfassung für den zuletzt abgeschlossenen Zeitraum sofort an %s (umgeht den Zeitplan).','Send test email'=>'Test-E-Mail senden','Search Console'=>'Search Console','Search Console connected. The first sync runs shortly.'=>'Search Console verbunden. Die erste Synchronisierung läuft in Kürze.','The last week is in. Older history is loading in the background a couple of weeks at a time, and should be complete in a few minutes.'=>'Die letzte Woche ist da. Ältere Daten werden im Hintergrund jeweils für ein paar Wochen nachgeladen und sollten in wenigen Minuten vollständig sein.','Search Console data refreshed.'=>'Search-Console-Daten aktualisiert.','Search Console disconnected.'=>'Search Console getrennt.','Brings in the searches people ran before they arrived. Google strips the query from the referrer, so this is the only place it exists. Uses the same kind of service account key as the Analytics importer, with read-only access.'=>'Bringt die Suchanfragen mit, die Leute vor ihrer Ankunft gestellt haben. Google entfernt die Suchanfrage aus dem Referrer, deshalb gibt es sie nur hier. Verwendet denselben Dienstkontoschlüssel-Typ wie der Analytics-Import, mit reinem Lesezugriff.','Under APIs and services, enable the Google Search Console API.'=>'Unter APIs und Dienste die Google Search Console API aktivieren.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com. You need that address for the next part.'=>'Unter IAM und Verwaltung, dann Dienstkonten, ein Dienstkonto erstellen. Dessen Adresse endet auf .iam.gserviceaccount.com. Diese Adresse wird im nächsten Schritt gebraucht.','In Search Console'=>'In Search Console','Open Settings, then Users and permissions, and add the service account address with Restricted access.'=>'Einstellungen öffnen, dann Nutzer und Berechtigungen, und die Dienstkonto-Adresse mit eingeschränktem Zugriff hinzufügen.','Copy the property exactly as Search Console lists it. A domain property looks like sc-domain:example.com. A URL-prefix property is the full address including https:// and any trailing slash. The two are different properties and the wrong one returns nothing.'=>'Die Property genau so kopieren, wie Search Console sie aufführt. Eine Domain-Property sieht aus wie sc-domain:example.com. Eine URL-Präfix-Property ist die vollständige Adresse inklusive https:// und einem eventuellen abschließenden Schrägstrich. Beides sind unterschiedliche Property-Typen, und die falsche liefert nichts zurück.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below.'=>'Dann die heruntergeladene Datei in einem Texteditor öffnen und sie komplett, mit den geschweiften Klammern, in das Feld unten einfügen.','The last sync failed: %s'=>'Die letzte Synchronisierung ist fehlgeschlagen: %s','Last refreshed %1$s ago, covering %2$s to %3$s.'=>'Zuletzt aktualisiert vor %1$s, für den Zeitraum %2$s bis %3$s.','Add %s as a user on the property in Search Console, with Restricted access.'=>'%s als Nutzer der Property in Search Console hinzufügen, mit eingeschränktem Zugriff.','Property'=>'Property','Copy it exactly as Search Console shows it. A domain property looks like sc-domain:example.com.'=>'Genau so kopieren, wie Search Console sie zeigt. Eine Domain-Property sieht aus wie sc-domain:example.com.','Save Search Console settings'=>'Search-Console-Einstellungen speichern','Fetch the last 90 days'=>'Die letzten 90 Tage abrufen','Disconnect'=>'Trennen','PageSpeed Insights'=>'PageSpeed Insights','API key saved. Tests now run from the dashboard and show their results there.'=>'API-Schlüssel gespeichert. Tests laufen jetzt über das Dashboard und zeigen ihre Ergebnisse dort an.','API key removed.'=>'API-Schlüssel entfernt.','The Page speed tab and each post\'s stats have a button for Google\'s lab test. Without a key it opens the test on the PageSpeed Insights website. With your own free Google API key, the test runs from here and the results show on the dashboard, next to the speed your real visitors got. A test only runs when someone presses the button.'=>'Auf dem Tab „Seitengeschwindigkeit“ und in den Statistiken jedes Beitrags findest du eine Schaltfläche für den Labortest von Google. Ohne Schlüssel wird der Test auf der Website von PageSpeed Insights geöffnet. Mit deinem eigenen kostenlosen Google-API-Schlüssel läuft der Test direkt hier, und die Ergebnisse erscheinen im Dashboard neben der Geschwindigkeit, die deine echten Besucher erlebt haben. Ein Test wird nur ausgeführt, wenn jemand auf die Schaltfläche klickt.','%s, or pick one you already have. Any name works.'=>'%s, oder wähle ein vorhandenes Projekt. Der Name ist beliebig.','Create a Google Cloud project'=>'Google-Cloud-Projekt erstellen','%s for that project.'=>'%s für dieses Projekt.','Enable the PageSpeed Insights API'=>'PageSpeed Insights API aktivieren','On the %s page, choose Create credentials, then API key.'=>'Wähle auf der Seite %s „Anmeldedaten erstellen“ und dann „API-Schlüssel“.','Credentials'=>'Anmeldedaten','Open the new key. Under API restrictions, choose Restrict key, select PageSpeed Insights API, and save.'=>'Öffne den neuen Schlüssel. Wähle unter „API-Einschränkungen“ die Option „Schlüssel einschränken“, wähle „PageSpeed Insights API“ und speichere.','Copy the key and paste it below.'=>'Kopiere den Schlüssel und füge ihn unten ein.','Google API key (optional)'=>'Google-API-Schlüssel (optional)','A key is saved.'=>'Ein Schlüssel ist gespeichert.','Save API key'=>'API-Schlüssel speichern','Remove API key'=>'API-Schlüssel entfernen','REST API'=>'REST-API','Endpoints and an example request'=>'Endpunkte und eine Beispielanfrage','Read-only endpoints under /wp-json/vireo-analytics/v1. Authenticate with WordPress Application Passwords or a logged-in session nonce. Requires the view_vireo_analytics capability.'=>'Schreibgeschützte Endpunkte unter /wp-json/vireo-analytics/v1. Authentifizieren Sie sich mit WordPress-Anwendungspasswörtern oder einem Nonce einer angemeldeten Sitzung. Erfordert die Berechtigung view_vireo_analytics.','Base URL'=>'Basis-URL','Endpoints'=>'Endpunkte','Example'=>'Beispiel','Connect an AI assistant'=>'KI-Assistenten verbinden','Ask Claude, Cursor or any other MCP client about this site\'s traffic in plain language: what changed this week, which pages are growing, what people searched for. The assistant signs in as you with an application password and sees exactly what you can see in the dashboard, read-only.'=>'Frag Claude, Cursor oder einen anderen MCP-Client in normaler Sprache nach dem Traffic dieser Website: was sich diese Woche geändert hat, welche Seiten wachsen, wonach Leute gesucht haben. Der Assistent meldet sich mit einem Anwendungspasswort als du an und sieht genau das, was du im Dashboard siehst, schreibgeschützt.','The bundled MCP adapter is missing from this install, so the endpoint is off. Reinstall the plugin from its release package.'=>'Der mitgelieferte MCP-Adapter fehlt in dieser Installation, daher ist der Endpunkt deaktiviert. Installiere das Plugin erneut aus seinem Release-Paket.','MCP endpoint'=>'MCP-Endpunkt','Copy'=>'Kopieren','Application password'=>'Anwendungspasswort','Create one on your profile'=>'Erstelle eins in deinem Profil','and name it after the assistant. Paste it where the snippets below say APP_PASSWORD; the spaces WordPress shows in it can stay. You can revoke it from the same place at any time.'=>'und benenne es nach dem Assistenten. Füge es dort ein, wo in den Snippets unten APP_PASSWORD steht; die Leerzeichen, die WordPress darin anzeigt, können bleiben. Du kannst es jederzeit an derselben Stelle widerrufen.','Only users who can open the Vireo dashboard can connect. A password for anyone else is refused.'=>'Nur Benutzer, die das Vireo-Dashboard öffnen können, dürfen sich verbinden. Ein Passwort für andere wird abgelehnt.','Claude Code'=>'Claude Code','Run it in a terminal, then ask Claude Code about your traffic.'=>'Führe es in einem Terminal aus und frag Claude Code dann nach deinem Traffic.','Claude Desktop, Cursor and others'=>'Claude Desktop, Cursor und andere','Add it to the client\'s MCP settings file (claude_desktop_config.json, Cursor\'s mcp.json). Needs Node.js on that computer; the proxy runs locally and talks to this site over HTTPS.'=>'Füge es in die MCP-Einstellungsdatei des Clients ein (claude_desktop_config.json, Cursors mcp.json). Node.js muss auf diesem Computer installiert sein; der Proxy läuft lokal und kommuniziert über HTTPS mit dieser Website.','Import data'=>'Daten importieren','Bring your history into Vireo Analytics. Your source data is never modified. An import adds to what is already stored and can\'t be undone, so import any range only once.'=>'Hol deine bisherigen Daten in Vireo Analytics. Deine Quelldaten werden nie verändert. Ein Import kommt zu den gespeicherten Daten hinzu und lässt sich nicht rückgängig machen. Importiere jeden Zeitraum also nur einmal.','Found on this site'=>'Auf dieser Website gefunden','A Google Analytics plugin is active on this site.'=>'Auf dieser Website ist ein Google-Analytics-Plugin aktiv.','Active, with data stored on this site.'=>'Aktiv, mit auf dieser Website gespeicherten Daten.','Active on this site.'=>'Auf dieser Website aktiv.','No longer active, but its data is still stored on this site.'=>'Nicht mehr aktiv, aber die Daten sind weiterhin auf dieser Website gespeichert.','None of the analytics plugins Vireo Analytics imports from is active on this site, and none has left data here. If you have used one of these, or still have its data elsewhere:'=>'Keines der Analytics-Plugins, aus denen Vireo Analytics importiert, ist auf dieser Website aktiv, und keines hat hier Daten hinterlassen. Falls du eines davon verwendet hast oder seine Daten noch anderswo vorliegen:','Vireo Analytics can also import from:'=>'Vireo Analytics kann außerdem importieren aus:','These import from the data a plugin leaves on this site. None was found yet:'=>'Diese importieren die Daten, die ein Plugin auf dieser Website hinterlässt. Bisher wurden keine gefunden:','Backup and restore'=>'Backup und Wiederherstellung','Download everything Vireo Analytics has recorded for this site as one file, and load it on another install, or back onto this one. Loading the same file twice gives the same numbers, so a restore can be repeated safely. Settings, connected sites and the live visitor buffer are not included.'=>'Lade alles herunter, was Vireo Analytics für diese Website aufgezeichnet hat, als eine Datei und spiele sie auf einer anderen Installation oder wieder auf dieser ein. Wird dieselbe Datei zweimal eingespielt, ergeben sich dieselben Zahlen, deshalb lässt sich eine Wiederherstellung gefahrlos wiederholen. Einstellungen, verbundene Websites und der Live-Besucherpuffer sind nicht enthalten.','Download backup'=>'Backup herunterladen','Restore from a backup'=>'Aus einem Backup wiederherstellen','Export CSV'=>'CSV exportieren','Download your analytics for the dates below as a CSV file. It\'s built on your server and goes straight to your browser.'=>'Lade deine Statistiken für die unten gewählten Daten als CSV-Datei herunter. Sie wird auf deinem Server erstellt und direkt an deinen Browser gesendet.','Site totals'=>'Website-Summen','Pages'=>'Seiten','Referrers'=>'Verweisquellen','Devices'=>'Geräte','Broken links'=>'Defekte Links','Events'=>'Ereignisse','Type'=>'Typ','Download CSV'=>'CSV herunterladen','Questions or a bug? %s.'=>'Fragen oder ein Fehler? %s.','Ask in the support forum'=>'Frag im Support-Forum nach','No 404 errors in this period'=>'Keine 404-Fehler in diesem Zeitraum','Broken links and missing pages hit by visitors will appear here.'=>'Defekte Links und fehlende Seiten, die von Besuchern aufgerufen werden, erscheinen hier.','Path'=>'Pfad','Top referrer'=>'Top-Verweisquelle','Hits'=>'Treffer','No broken links'=>'Keine defekten Links','Nothing on your site links to a page that is missing.'=>'Nichts auf deiner Website verlinkt auf eine fehlende Seite.','Pages on your site linking somewhere missing. Fix the linking page.'=>'Seiten auf deiner Website, die auf etwas Fehlendes verlinken. Die verlinkende Seite korrigieren.','Missing page'=>'Fehlende Seite','Linked from'=>'Verlinkt von','+%s more page'=>'+%s weitere Seite' . "\0" . '+%s weitere Seiten','Requests from elsewhere'=>'Anfragen von anderswo','Nothing on your site links to these. Mostly automated scanners looking for software you do not run; occasionally a stale link elsewhere worth a redirect.'=>'Nichts auf deiner Website verlinkt hierher. Meist automatisierte Scanner, die nach Software suchen, die du nicht einsetzt; gelegentlich ein veralteter Link anderswo, der eine Weiterleitung wert ist.','Referrer'=>'Referrer','no referrer'=>'kein Referrer','requests from their crawlers'=>'Anfragen ihrer Crawler','readers they sent back'=>'gesendete Leser','crawler requests per reader sent'=>'Crawler-Anfragen pro vermitteltem Leser','Since %s, when Vireo started counting crawlers. Earlier days in this range have readers but no crawler figures, so this card leaves them out.'=>'Seit %s, als Vireo begonnen hat, Crawler zu zählen. Frühere Tage in diesem Zeitraum enthalten Leser, aber keine Crawler-Zahlen, deshalb lässt diese Karte sie aus.','Assistant'=>'Assistent','Readers sent'=>'Gesendete Leser','No assistant has sent a reader to this site in this period, though their crawlers have been reading it.'=>'Kein Assistent hat in diesem Zeitraum einen Leser zu dieser Website gesendet, obwohl ihre Crawler sie gelesen haben.','Crawler figures count requests the bot filter held back. Readers sent counts people who arrived by following a link inside an assistant, which is the closest thing there is to being recommended by one.'=>'Crawler-Zahlen zählen Anfragen, die der Bot-Filter zurückgehalten hat. Gesendete Leser zählt Personen, die über einen Link in einem Assistenten ankamen, was einer Empfehlung durch ihn am nächsten kommt.','Notes'=>'Notizen','Remove the note for %s'=>'Notiz vom %s entfernen','Nothing noted in this range yet.'=>'In diesem Zeitraum noch nichts notiert.','Date'=>'Datum','What happened'=>'Was passiert ist','Newsletter went out'=>'Newsletter verschickt','Add note'=>'Notiz hinzufügen','%s request kept out of the numbers above.'=>'%s Anfrage ist in den obigen Zahlen nicht enthalten.' . "\0" . '%s Anfragen sind in den obigen Zahlen nicht enthalten.','That is under 0.1%% of the requests Vireo saw.'=>'Das sind weniger als 0,1 %% der Anfragen, die Vireo erfasst hat.','That is %s%% of the requests Vireo saw.'=>'Das sind %s%% der Anfragen, die Vireo gesehen hat.','What was filtered and why'=>'Was gefiltert wurde und warum','None of these reached your visitor or pageview totals. It is also why those totals sit below what a server-log tool reports: log readers count every crawler, monitor and scraper as a visit. Crawlers are counted when they ask WordPress for a page, so on a site with full-page caching the real numbers are higher than these: a cached page is answered before WordPress runs, and nothing inside WordPress can see that request.'=>'Keiner davon ist in deine Besucher- oder Seitenaufruf-Summen eingeflossen. Das ist auch, warum diese Summen unter dem liegen, was ein Server-Log-Tool meldet: Log-Reader zählen jeden Crawler, Monitor und Scraper als Besuch. Crawler werden gezählt, wenn sie WordPress um eine Seite bitten, deshalb sind die echten Zahlen auf einer Website mit vollständigem Seiten-Caching höher als diese: Eine gecachte Seite wird beantwortet, bevor WordPress läuft, und nichts innerhalb von WordPress kann diese Anfrage sehen.','Got it'=>'Verstanden','Both'=>'Beide','Prior period'=>'Vorzeitraum','Hourly traffic'=>'Stündlicher Traffic','Daily traffic'=>'Täglicher Traffic','Chart granularity'=>'Diagramm-Granularität','Chart metric'=>'Diagramm-Metrik','%s, whole days'=>'%s, ganze Tage','No traffic yet'=>'Noch kein Traffic','Pageviews for the selected range will plot here as they are recorded.'=>'Seitenaufrufe für den ausgewählten Bereich werden hier dargestellt, sobald sie erfasst werden.','View'=>'Ansicht','Map'=>'Karte','Table'=>'Tabelle','Countries are not being resolved'=>'Länder werden nicht aufgelöst','The geo-location database is not installed, so every visitor is recorded as unknown. Your traffic is still being counted.'=>'Die Geolokalisierungs-Datenbank ist nicht installiert, daher wird jeder Besucher als unbekannt erfasst. Ihr Traffic wird dennoch gezählt.','Set it up'=>'Jetzt einrichten','No country data yet'=>'Noch keine Länderdaten','Geo-located pageviews will appear here once visitors arrive.'=>'Geolokalisierte Seitenaufrufe erscheinen hier, sobald Besucher eintreffen.','World map of visitor distribution'=>'Weltkarte der Besucherverteilung','Country known for %s%% of visitors.'=>'Das Land ist bei %s %% der Besucher bekannt.','Filter by %s'=>'Nach %s filtern','Device types'=>'Gerätetypen','Browsers'=>'Browser','Operating systems'=>'Betriebssysteme','Technology breakdown'=>'Technologie-Aufschlüsselung','No data for this period.'=>'Keine Daten für diesen Zeitraum.','visitor'=>'Besucher' . "\0" . 'Besucher','Gained'=>'Zugewinne','Nothing grew.'=>'Nichts ist gewachsen.','Lost'=>'Verluste','Nothing fell.'=>'Nichts ist gefallen.','Show all pages'=>'Alle Seiten anzeigen','Sources'=>'Quellen','Show all sources'=>'Alle Quellen anzeigen','Fix this'=>'Beheben','&larr; Overview'=>'&larr; Übersicht','Total count'=>'Gesamtanzahl','times recorded in this range'=>'Mal in diesem Zeitraum erfasst','Unique visitors'=>'Eindeutige Besucher','daily visitors, added up'=>'tägliche Besucher, addiert','Distinct values'=>'Verschiedene Werte','in this range, top %d listed below'=>'in diesem Zeitraum, die Top %d unten','in this range'=>'in diesem Zeitraum','Daily counts'=>'Tägliche Anzahl','Count'=>'Anzahl','Unique'=>'Eindeutig','Nothing recorded in this range'=>'In diesem Zeitraum nichts erfasst','Event counts for the selected range will plot here as they are recorded.'=>'Die Ereigniszahlen für den ausgewählten Bereich werden hier dargestellt, sobald sie erfasst werden.','Top values'=>'Top-Werte','No values recorded'=>'Keine Werte erfasst','Send a value with this event to see a breakdown here.'=>'Sende mit diesem Ereignis einen Wert, um hier eine Aufschlüsselung zu sehen.','(no value)'=>'(kein Wert)','&larr; back to all events'=>'&larr; zurück zu allen Ereignissen','Top events'=>'Top-Ereignisse','No events recorded'=>'Keine Ereignisse erfasst','Fire events from your site with <code>vireo(\'event\', \'name\')</code> and they\'ll appear here.'=>'Lösen Sie Ereignisse von Ihrer Website mit <code>vireo(\'event\', \'name\')</code> aus, und sie erscheinen hier.','not available with these filters'=>'mit diesen Filtern nicht verfügbar','in the selected range'=>'im ausgewählten Zeitraum','daily uniques, summed'=>'tägliche eindeutige Besucher, summiert','unique today'=>'eindeutig heute','Someone who visits on more than one day is counted once per day. Visitors are identified by a hash whose salt is regenerated every night, so the same person cannot be recognised across days. That is deliberate: it is what lets Vireo track visitors without cookies and without consent.'=>'Wer an mehr als einem Tag besucht, wird einmal pro Tag gezählt. Besucher werden über einen Hash identifiziert, dessen Salt jede Nacht neu erzeugt wird, sodass dieselbe Person nicht über mehrere Tage hinweg wiedererkannt werden kann. Das ist beabsichtigt: Genau das ermöglicht es Vireo, Besucher ohne Cookies und ohne Einwilligung zu erfassen.','Unique visitors today.'=>'Eindeutige Besucher heute.','Average daily traffic'=>'Durchschnittlicher täglicher Traffic','over %d day'=>'über %d Tag' . "\0" . 'über %d Tage','not split by filters'=>'nicht nach Filtern aufgeschlüsselt','Time on page is measured for the whole site, so it is not shown while a filter is on.'=>'Die Verweildauer wird für die gesamte Website gemessen und deshalb nicht angezeigt, solange ein Filter aktiv ist.','average active time'=>'durchschnittliche aktive Zeit','The average of the %s view that reported a time. Only time with the tab in front of the reader counts, up to 30 minutes a view, and views closed before they reported are left out.'=>'Der Durchschnitt aus dem %s Aufruf, der eine Zeit gemeldet hat. Es zählt nur die Zeit, in der der Tab im Vordergrund war, höchstens 30 Minuten pro Aufruf. Aufrufe, die vor der Meldung geschlossen wurden, bleiben unberücksichtigt.' . "\0" . 'Der Durchschnitt aus den %s Aufrufen, die eine Zeit gemeldet haben. Es zählt nur die Zeit, in der der Tab im Vordergrund war, höchstens 30 Minuten pro Aufruf. Aufrufe, die vor der Meldung geschlossen wurden, bleiben unberücksichtigt.','Time on page'=>'Verweildauer','Bounce rate is measured for the whole site, so it is not shown while a filter is on.'=>'Die Absprungrate wird für die gesamte Website gemessen und deshalb nicht angezeigt, solange ein Filter aktiv ist.','visitors who viewed one page'=>'Besucher, die eine Seite aufgerufen haben','The share of visitors who viewed exactly one page in a day. A visitor is counted the same way as on the Visitors card, once per day, so someone who comes back on another day counts again.'=>'Der Anteil der Besucher, die an einem Tag genau eine Seite aufgerufen haben. Ein Besucher wird wie in der Karte „Besucher“ gezählt, einmal pro Tag. Wer an einem anderen Tag wiederkommt, zählt also erneut.','Bounce rate'=>'Absprungrate','The %1$s figures come from history imported from %2$s.'=>'Die Zahlen für %1$s stammen aus dem Verlauf, der aus %2$s importiert wurde.','This week'=>'Diese Woche','Compared with the same period last year, up to the same time of day.'=>'Im Vergleich zum gleichen Zeitraum des Vorjahres, bis zur selben Tageszeit.','Compared with the same period last year.'=>'Im Vergleich zum gleichen Zeitraum des Vorjahres.','Compared with the period before, up to the same time of day.'=>'Verglichen mit dem Vorzeitraum bis zur gleichen Uhrzeit.','Compared with the period before.'=>'Verglichen mit dem Vorzeitraum.','Performance score'=>'Performance-Wert','What Google suggests fixing first'=>'Was Google zuerst zu beheben empfiehlt','Nothing with a measurable saving. This page passed the checks that matter most.'=>'Nichts mit messbarem Einsparpotenzial. Diese Seite hat die wichtigsten Prüfungen bestanden.','Tested as a desktop visitor %s ago.'=>'Vor %s als Desktop-Besucher getestet.','Tested as a phone visitor %s ago.'=>'Vor %s als Handy-Besucher getestet.','Run again'=>'Erneut ausführen','Full report on PageSpeed Insights'=>'Vollständiger Bericht auf PageSpeed Insights','(opens in a new tab)'=>'(öffnet in einem neuen Tab)','Lab: one test by Google'=>'Labor: ein Test von Google','Device to test as'=>'Gerät für den Test','Test this page on PageSpeed Insights'=>'Diese Seite mit PageSpeed Insights testen','Add a free Google API key in Settings to see the results right here instead.'=>'Füge in den Einstellungen einen kostenlosen Google-API-Schlüssel hinzu, um die Ergebnisse stattdessen direkt hier zu sehen.','An administrator can add a free Google API key in Settings to show the results right here instead.'=>'Ein Administrator kann in den Einstellungen einen kostenlosen Google-API-Schlüssel hinzufügen, um die Ergebnisse stattdessen direkt hier anzuzeigen.','Google loads this page once on its own servers, as a desktop visitor, and lists what would make it faster. It takes up to a minute.'=>'Google lädt diese Seite einmal auf seinen eigenen Servern, als Desktop-Besucher, und listet auf, was sie schneller machen würde. Das dauert bis zu einer Minute.','Google loads this page once on its own servers, as a phone visitor on a slow connection, and lists what would make it faster. It takes up to a minute.'=>'Google lädt diese Seite einmal auf seinen eigenen Servern, als Handy-Besucher mit langsamer Verbindung, und listet auf, was sie schneller machen würde. Das dauert bis zu einer Minute.','Run test'=>'Test starten','Lifetime pageviews'=>'Seitenaufrufe insgesamt','since %s'=>'seit %s','Lifetime visitors'=>'Besucher insgesamt','Best day'=>'Bester Tag','no traffic yet'=>'noch kein Traffic','Daily traffic · %1$s &ndash; %2$s'=>'Täglicher Traffic · %1$s &ndash; %2$s','No traffic in this range'=>'Kein Traffic in diesem Zeitraum','Pageviews for this post will plot here as they are recorded.'=>'Seitenaufrufe für diesen Beitrag werden hier dargestellt, sobald sie erfasst werden.','pageviews in range'=>'Seitenaufrufe im Zeitraum','visitors in range'=>'Besucher im Zeitraum','comment in range'=>'Kommentar im Zeitraum' . "\0" . 'Kommentare im Zeitraum','comments per 1,000 views'=>'Kommentare pro 1.000 Aufrufe','Page speed for this post'=>'Seitengeschwindigkeit für diesen Beitrag','Speed from your real visitors is measured for the whole site, not per post.'=>'Die Geschwindigkeit deiner echten Besucher wird für die gesamte Website gemessen, nicht pro Beitrag.','See it on the Overview'=>'In der Übersicht ansehen','This post, tested by Google'=>'Dieser Beitrag, von Google getestet','Test this post with Google'=>'Diesen Beitrag mit Google testen','Top referrers for this post'=>'Top-Verweisquellen für diesen Beitrag','No referrers in this range'=>'Keine Verweisquellen in diesem Zeitraum','This post had no inbound referrers during the selected period.'=>'Für diesen Beitrag gab es im ausgewählten Zeitraum keine eingehenden Verweisquellen.','Per-post referrer data is being collected'=>'Verweisdaten pro Beitrag werden gesammelt','Referrers per individual post started tracking with a recent update. Data will appear here as new visitors arrive.'=>'Die Erfassung von Verweisquellen pro einzelnem Beitrag begann mit einem kürzlichen Update. Daten erscheinen hier, sobald neue Besucher eintreffen.','Referrer data for this post starts from %s.'=>'Verweisdaten für diesen Beitrag beginnen ab %s.','Searches that found this post'=>'Suchanfragen, die diesen Beitrag gefunden haben','See what people searched for'=>'Sieh dir an, wonach gesucht wurde','Only Search Console knows which searches showed this post. Connect it to list them here.'=>'Nur die Search Console weiß, bei welchen Suchen dieser Beitrag erschien. Verbinde sie, um die Suchen hier zu sehen.','Connect Search Console'=>'Search Console verbinden','No searches for this post in this range'=>'Keine Suchanfragen für diesen Beitrag in diesem Zeitraum','Google reports search data about three days late, so the most recent days are always empty.'=>'Google meldet Suchdaten etwa drei Tage verspätet, deshalb sind die jüngsten Tage immer leer.','Clicks · position'=>'Klicks · Position','Shown %s time'=>'%s-mal angezeigt' . "\0" . '%s-mal angezeigt','%1$s. Printed %2$s from Vireo Analytics.'=>'%1$s. Gedruckt am %2$s aus Vireo Analytics.','Traffic from this referrer · %1$s to %2$s'=>'Traffic von dieser Verweisquelle · %1$s bis %2$s','Pageviews in range'=>'Seitenaufrufe im Zeitraum','Visitors in range'=>'Besucher im Zeitraum','No traffic from this referrer in this range'=>'Kein Traffic von dieser Verweisquelle in diesem Zeitraum','Pageviews sent by this source will plot here as they are recorded.'=>'Seitenaufrufe, die von dieser Quelle gesendet werden, werden hier dargestellt, sobald sie erfasst werden.','Posts it sent people to'=>'Beiträge, auf die sie verwiesen hat','Pageviews on each post from this referrer. Home and archive pages aren\'t broken down this way.'=>'Seitenaufrufe je Beitrag von dieser Verweisquelle. Startseite und Archivseiten werden so nicht aufgeschlüsselt.','Vireo has been counting here for %s day. If it has been useful, a review on WordPress.org helps other site owners find it.'=>'Vireo zählt hier seit %s Tag. Wenn es dir nützlich war, hilft eine Bewertung auf WordPress.org anderen Website-Betreibern, es zu finden.' . "\0" . 'Vireo zählt hier seit %s Tagen. Wenn es dir nützlich war, hilft eine Bewertung auf WordPress.org anderen Website-Betreibern, es zu finden.','Leave a review'=>'Bewertung abgeben','Not now'=>'Jetzt nicht','Don\'t ask again'=>'Nicht erneut fragen','Searches that found you'=>'Suchanfragen, die dich gefunden haben','clicks from search'=>'Klicks aus der Suche','times you appeared'=>'Erscheinungen in der Suche','click-through rate'=>'Klickrate','average position'=>'durchschnittliche Position','Clicks'=>'Klicks','Impressions'=>'Impressionen','Position'=>'Position','The page Google most often showed for this search'=>'Die Seite, die Google für diese Suche am häufigsten angezeigt hat','From Search Console, which reports a few days behind and leaves out rare searches.'=>'Aus Search Console, das ein paar Tage verzögert berichtet und seltene Suchanfragen auslässt.','posts opened'=>'geöffnete Beiträge','links followed from a post'=>'aus einem Beitrag aufgerufene Links','Follow clicks'=>'Folgen-Klicks','Load more clicks'=>'Klicks auf „Mehr laden“','Instagram feeds'=>'Instagram-Feeds','Page with a feed'=>'Seite mit Feed','Posts opened'=>'Geöffnete Beiträge','No pages tracked yet'=>'Noch keine Seiten erfasst','Top posts and pages will appear here after the first few visits.'=>'Top-Beiträge und -Seiten erscheinen hier nach den ersten Besuchen.','Average active time on this page: %s'=>'Durchschnittliche aktive Zeit auf dieser Seite: %s','(unpublished)'=>'(unveröffentlicht)','Visitors who arrived with no referrer: typed the URL, used a bookmark, or came from an app or email client.'=>'Besucher, die ohne Verweisquelle kamen: haben die URL eingegeben, ein Lesezeichen verwendet oder kamen aus einer App oder einem E-Mail-Programm.','No search traffic in this range.'=>'Kein Suchtraffic in diesem Zeitraum.','No AI assistant traffic in this range.'=>'Kein Traffic von KI-Assistenten in diesem Zeitraum.','No social traffic in this range.'=>'Kein Traffic aus sozialen Netzwerken in diesem Zeitraum.','No referral traffic in this range.'=>'Kein Verweis-Traffic in diesem Zeitraum.','No referrers yet'=>'Noch keine Verweisquellen','When someone clicks through from another site, they\'ll show up here.'=>'Wenn jemand von einer anderen Website aus durchklickt, erscheint er hier.','None of these made the top ten. Filter by this source to list them.'=>'Keine davon hat es in die Top 10 geschafft. Filtere nach dieser Quelle, um sie aufzulisten.','Every visit from this site viewed one page and none landed on a post, over a burst of days. That is what a compromised site or a spoofed referrer looks like, not readers. Nothing is removed until you block it.'=>'Alle Besuche von dieser Website haben nur eine Seite aufgerufen, und keiner ist bei einem Beitrag gelandet, über mehrere Tage hinweg in kurzer Folge. So sieht eine gehackte Website oder ein gefälschter Referrer aus, nicht echte Leser. Es wird nichts entfernt, bis du es blockierst.','suspected junk'=>'vermuteter Spam','Block this referrer'=>'Diesen Referrer blockieren','Page speed from real visits'=>'Seitengeschwindigkeit aus echten Besuchen','No speed measurements from real visits in this range yet. They appear as people load your pages.'=>'In diesem Zeitraum gibt es noch keine Geschwindigkeitsmessungen von echten Besuchen. Sie erscheinen, sobald Besucher deine Seiten laden.','75th percentile: three in four visits were at least this fast.'=>'75. Perzentil: Drei von vier Besuchen waren mindestens so schnell.','Google grades pages on this line rather than the average, so the slowest quarter of visits counts against you.'=>'Google bewertet Seiten nach diesem Wert statt nach dem Durchschnitt, daher zählt das langsamste Viertel der Besuche gegen dich.','Only %s real visit measured so far, so expect these to move.'=>'Bisher erst %s echter Besuch gemessen, die Werte können sich also noch ändern.' . "\0" . 'Bisher erst %s echte Besuche gemessen, die Werte können sich also noch ändern.','Measured from %s real visit, not a lab test.'=>'Gemessen an %s echtem Besuch, nicht in einem Labortest.' . "\0" . 'Gemessen an %s echten Besuchen, nicht in einem Labortest.','Your homepage, tested by Google'=>'Deine Startseite, von Google getestet','Test your homepage with Google'=>'Deine Startseite mit Google testen','Aggregated content'=>'Aggregierte Inhalte','views of imported posts'=>'Aufrufe importierter Beiträge','clicks through to the original articles'=>'Klicks zu den Originalartikeln','of all pageviews were imported posts'=>'aller Seitenaufrufe entfielen auf importierte Beiträge','Feed source'=>'Feed-Quelle','Views here'=>'Aufrufe hier','Clicks out'=>'Klicks nach außen','Clicks out count readers who followed an item to the site it came from, recorded from the day this version of Vireo was installed.'=>'Klicks nach außen zählen Leser, die einem Eintrag zur Website gefolgt sind, von der er stammt. Sie werden ab dem Tag erfasst, an dem diese Version von Vireo installiert wurde.','Views here count visits to items imported as posts.'=>'Aufrufe hier zählen Besuche bei Einträgen, die als Beiträge importiert wurden.','Your %d in review is ready.'=>'Dein %d in der Prüfung ist fertig.','See it'=>'Ansehen','%d so far'=>'%d bisher','%d in review'=>'%d in Prüfung','vs the same days of %d'=>'vs. dieselben Tage von %d','vs %d'=>'vs. %d','No full record of %d to compare with'=>'Keine vollständige Aufzeichnung von %d zum Vergleichen','Year'=>'Jahr','Copy summary'=>'Zusammenfassung kopieren','Print'=>'Drucken','Nothing recorded for %d yet'=>'Für %d wurde noch nichts erfasst','This review fills in on its own as visits are recorded; the first ones show up within a minute. If another analytics tool counted this year, its history can be imported and shows here marked as imported.'=>'Dieser Rückblick füllt sich von selbst, sobald Besuche erfasst werden; die ersten erscheinen innerhalb einer Minute. Hat ein anderes Analysetool dieses Jahr gezählt, lässt sich sein Verlauf importieren und erscheint hier als importiert.','Import history'=>'Verlauf importieren','Part of one year was imported from another tool, which counts in its own way, so read the change as a rough guide.'=>'Ein Teil eines Jahres wurde aus einem anderen Tool importiert, das anders zählt. Verstehe die Veränderung daher als grobe Orientierung.','Daily visitors added up. Someone who came on three different days counts three times, because Vireo can\'t recognise anyone from one day to the next.'=>'Tägliche Besucher aufsummiert. Wer an drei verschiedenen Tagen kam, wird dreimal gezählt, weil Vireo niemanden von einem Tag zum nächsten wiedererkennen kann.','Busiest month'=>'Stärkster Monat','Busiest day: %1$s, with %2$s pageview.'=>'Stärkster Tag: %1$s mit %2$s Seitenaufruf.' . "\0" . 'Stärkster Tag: %1$s mit %2$s Seitenaufrufen.','Pageviews by month'=>'Seitenaufrufe pro Monat','still to come'=>'steht noch aus','%s pageviews so far this month'=>'%s Seitenaufrufe bisher in diesem Monat','%s pageviews, imported'=>'%s Seitenaufrufe, importiert','%1$s pageviews, %2$s of them imported'=>'%1$s Seitenaufrufe, davon %2$s importiert','%s pageviews'=>'%s Seitenaufrufe','so far'=>'bisher','Counted by Vireo Analytics'=>'Gezählt von Vireo Analytics','Imported'=>'Importiert','Where these numbers come from'=>'Woher diese Zahlen stammen','%1$s pageviews this year came from imports and %2$s were counted by Vireo. Imported months are as the other tool counted them, which rarely matches Vireo exactly: tools filter bots and count visitors differently.'=>'%1$s Seitenaufrufe in diesem Jahr stammen aus Importen und %2$s wurden von Vireo gezählt. Importierte Monate entsprechen der Zählung des anderen Tools, die selten genau mit Vireo übereinstimmt: Tools filtern Bots und zählen Besucher unterschiedlich.','No page-level data for this year.'=>'Keine Daten auf Seitenebene für dieses Jahr.','Published in %d'=>'Veröffentlicht in %d','Nothing published this year has been viewed yet.'=>'In diesem Jahr veröffentlichte Beiträge wurden noch nicht aufgerufen.','Countries from %s onward. Earlier history has no country data.'=>'Länder ab %s. Für frühere Daten liegen keine Länderdaten vor.','Visitors, added up day by day.'=>'Besucher, Tag für Tag aufsummiert.','No country data for this year.'=>'Keine Länderdaten für dieses Jahr.','How people arrived, in pageviews'=>'Wie Besucher kamen, in Seitenaufrufen','mostly %1$s (%2$s)'=>'meist %1$s (%2$s)','No referrer data for this year.'=>'Keine Referrer-Daten für dieses Jahr.','Top Google searches'=>'Top-Google-Suchanfragen','%1$s clicks from %2$s appearances in Google results.'=>'%1$s Klicks bei %2$s Anzeigen in den Google-Ergebnissen.','requests from AI crawlers'=>'Anfragen von KI-Crawlern','readers sent back'=>'zurückgeschickte Leser','Since %s, when Vireo started counting. Imported history doesn\'t record crawlers, so earlier months are left out of both numbers.'=>'Seit %s, als Vireo mit dem Zählen begonnen hat. Importierte Verlaufsdaten enthalten keine Crawler, daher bleiben frühere Monate in beiden Zahlen unberücksichtigt.','%s crawler requests for every reader sent.'=>'%s Crawler-Anfragen pro vermitteltem Leser.','Your day on %s'=>'Dein Tag auf %s','Your daily snapshot · %s'=>'Dein Tagesüberblick · %s','change against the previous dayDoD'=>'ggü. Vortag','Your month on %s'=>'Dein Monat auf %s','Your monthly snapshot · %s'=>'Dein Monatsüberblick · %s','change against the previous monthMoM'=>'ggü. Vormonat','Your week on %s'=>'Deine Woche auf %s','Your weekly snapshot · %s'=>'Dein Wochenüberblick · %s','change against the previous weekWoW'=>'ggü. Vorwoche','Every minute (Vireo Analytics)'=>'Jede Minute (Vireo Analytics)','%s event'=>'%s Ereignis' . "\0" . '%s Ereignisse','Daily traffic chart, no data.'=>'Diagramm täglicher Traffic, keine Daten.','Daily traffic, %1$s to %2$s. %3$s, %4$s. Use arrow keys to step through each day.'=>'Täglicher Traffic, %1$s bis %2$s. %3$s, %4$s. Mit den Pfeiltasten gehst du durch die einzelnen Tage.','%1$s: %2$s, %3$s'=>'%1$s: %2$s, %3$s',', %s pageview in the prior period'=>', %s Seitenaufruf im Vorzeitraum' . "\0" . ', %s Seitenaufrufe im Vorzeitraum','Note: %s'=>'Hinweis: %s','Note on %1$s: %2$s'=>'Hinweis zu %1$s: %2$s','%1$s: %2$s'=>'%1$s: %2$s','Show fewer'=>'Weniger anzeigen','Saving…'=>'Speichern…','View saved.'=>'Ansicht gespeichert.','The view could not be saved.'=>'Die Ansicht konnte nicht gespeichert werden.','Forgetting…'=>'Wird vergessen…','View forgotten.'=>'Ansicht vergessen.','The view could not be forgotten.'=>'Die Ansicht konnte nicht vergessen werden.','Block %s? Its visits will be filtered like bots from now on and hidden from reports.'=>'%s blockieren? Seine Besuche werden ab jetzt wie Bots gefiltert und aus den Berichten ausgeblendet.','%1$s moved to position %2$d of %3$d.'=>'%1$s an Position %2$d von %3$d verschoben.','Copied'=>'Kopiert','Select the text and copy it yourself'=>'Markiere den Text und kopiere ihn selbst','No answer yet. If the test finishes, its result shows here when you reload the page in a minute.'=>'Noch keine Antwort. Wenn der Test abgeschlossen wird, erscheint das Ergebnis hier, sobald du die Seite in einer Minute neu lädst.','Testing on Google\'s servers, which takes up to a minute. %ds so far.'=>'Der Test läuft auf den Servern von Google und dauert bis zu einer Minute. Bisher %ds.','Test finished.'=>'Test abgeschlossen.','Request failed.'=>'Anfrage fehlgeschlagen.','Network error — try again.'=>'Netzwerkfehler – bitte erneut versuchen.','Post types'=>'Beitragstypen','At least one type stays selected.'=>'Mindestens ein Typ bleibt ausgewählt.','Number of posts'=>'Anzahl der Beiträge','Period'=>'Zeitraum','Display'=>'Anzeige','Posts without a featured image are listed by title only.'=>'Beiträge ohne Beitragsbild erscheinen nur mit ihrem Titel.','No posts of the selected types have views in this period yet. Visitors see nothing here until they do.'=>'Noch keine Beiträge der gewählten Typen mit Aufrufen in diesem Zeitraum. Besucher sehen hier nichts, bis es welche gibt.','Count views from'=>'Aufrufe zählen von','Shows this post\'s view count on the site.'=>'Zeigt die Aufrufzahl dieses Beitrags auf der Website an.','block titlePopular posts'=>'Beliebte Beiträge','block descriptionYour most viewed posts, counted by Vireo Analytics.'=>'Deine meistaufgerufenen Beiträge, gezählt von Vireo Analytics.','block keywordtop posts'=>'Top-Beiträge','block keywordmost viewed'=>'meistaufgerufen','block keywordtrending'=>'im Trend','block keywordanalytics'=>'Analytics','block titlePost views'=>'Beitragsaufrufe','block descriptionHow many times this post has been viewed, counted by Vireo Analytics.'=>'Wie oft dieser Beitrag aufgerufen wurde, gezählt von Vireo Analytics.','block keywordviews'=>'Aufrufe','block keywordpageviews'=>'Seitenaufrufe','block keywordcounter'=>'Zähler']];